export function UniqueKeyMenu({ x, y, nodeId }) {
  const { nodes, edges, updateHelpers, currentIndex, setContextMenu } = useGraph();

  // Close on Escape (clicks outside are handled by the ClickAwayListener below).
  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") setContextMenu(null); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [setContextMenu]);

  const matchedNode = nodes.find(n => n.data?.helpers?.uuid === nodeId);
  const rawProperties = matchedNode?.data?.properties || {};

  const properties = Object.fromEntries(
    Object.entries(rawProperties).filter(([key, val]) => {
      // static property = primitive value
      return typeof val !== "object" || val === null;
    })
  );

  // --- Outgoing / incoming edges ---
  const outgoing = edges.filter(e => e.source === matchedNode.id);
  const incoming = edges.filter(e => e.target === matchedNode.id);

  const getEdgeLabel = (edge) => {
    const t = edge.data.temporalLabels;
    return typeof t === "object" ? (t[currentIndex] ?? null) : t;
  };
  const getTargetLabel = (edge) => {
    return nodes.find(n => n.id === edge.target)?.data?.label || edge.target;
  };
  const getSourceLabel = (edge) => {
    return nodes.find(n => n.id === edge.source)?.data?.label || edge.source;
  };

  // ---- Current uniqueKey selection for this frame ----
  // uniqueKey is a dict: { ts: ["propA", "edge7"], ... }
  const uniqueKeyMap = matchedNode?.data?.helpers?.uniqueKey || {};

  // The timestamp we are editing
  const tsList = Object.keys(matchedNode?.data?.visibleAt || {}).map(Number);

  // Current frame's selected items
  const selected = uniqueKeyMap[currentIndex] || [];

  const toggle = (token) => {
    const isEdge = edges.some(e => e.id === token);

    // --- CASE: currently selected → remove it ---
    const currentlyOn = (uniqueKeyMap[currentIndex] || []).includes(token);

    if (currentlyOn) {
      if (token === "is unique" || !isEdge) {
        // REMOVE FROM ALL FRAMES (STATIC OR is_unique)
        tsList.forEach(ts => {
          const list = uniqueKeyMap[ts] || [];
          const updated = list.filter(t => t !== token);
          updateHelpers(nodeId, "uniqueKey", updated, ts);
        });
      } else {
        // REMOVE EDGE ONLY FROM FRAMES WHERE IT EXISTS
        const edge = edges.find(e => e.id === token);
        const temporal = edge?.data?.temporalLabels;

        tsList.forEach(ts => {
          const existsAtTs =
            typeof temporal === "string" ||
            (temporal && temporal[ts] !== undefined);
          if (!existsAtTs) return;

          const list = uniqueKeyMap[ts] || [];
          const updated = list.filter(t => t !== token);
          updateHelpers(nodeId, "uniqueKey", updated, ts);
        });
      }

      return;
    }

    // --- CASE: turning ON a token ---

    // SPECIAL CASE: is_unique overwrites all frames
    if (token === "is unique") {
      tsList.forEach(ts => {
        updateHelpers(nodeId, "uniqueKey", ["is unique"], ts);
      });
      return;
    }

    if (!isEdge) {
      // STATIC PROPERTY → add to all frames
      tsList.forEach(ts => {
        const list = uniqueKeyMap[ts] || [];
        if (!list.includes(token)) {
          const updated = [...list, token];
          updateHelpers(nodeId, "uniqueKey", updated, ts);
        }
      });
      return;
    }

    // EDGE → add to frames where edge exists
    const edge = edges.find(e => e.id === token);
    const temporal = edge?.data?.temporalLabels;

    tsList.forEach(ts => {
      const existsAtTs =
        typeof temporal === "string" ||
        (temporal && temporal[ts] !== undefined);

      if (!existsAtTs) return;

      const list = uniqueKeyMap[ts] || [];
      if (!list.includes(token)) {
        const updated = [...list, token];
        updateHelpers(nodeId, "uniqueKey", updated, ts);
      }
    });
  };

  return (
    <ClickAwayListener onClickAway={() => setContextMenu(null)}>
    <Paper
      elevation={4}
      style={{
        position: "absolute",
        top: y + 20,
        left: x + 10,
        transform: "translate(-50%)",
        padding: "6px",
        zIndex: 999999,
        background: "#222",
        color: "white",
        borderRadius: "6px",
        width: "270px",
        maxHeight: `calc(100vh - 68px - ${y}px + 20px)`,
        overflow: "scroll"
      }}
    >
      {/* --- IS UNIQUE FLAG --- */}
      <FormControlLabel
        control={
          <Checkbox
            checked={selected.includes("is unique")}
            onChange={() => toggle("is unique")}
            sx={{ color: "white" }}
          />
        }
        label="is unique"
        sx={{ color: "white" }}
      />

      {/* --- Properties --- */}
      {!selected.includes("is unique") && <Box sx={{ fontSize: "0.7rem", marginTop: "6px", opacity: 0.7 }}>
        Properties
      </Box>}

      {!selected.includes("is unique") && Object.keys(properties).map((key) => (
        <FormControlLabel
          key={key}
          control={
            <Checkbox
              checked={(selected || []).includes(key)}
              onChange={() => toggle(key)}
              sx={{ color: "white" }}
            />
          }
          label={`${key}: ${properties[key]}`}
          sx={{
            color: "white",
            ml: 1,
            "&:hover": { backgroundColor: "#333" },
            borderRadius: "4px"
          }}
        />
      ))}

      {/* Divider */}
      {(outgoing.length > 0 || incoming.length > 0) && !selected.includes("is unique") && (
        <Box
          sx={{
            marginTop: "8px",
            marginBottom: "4px",
            borderTop: "1px solid #555",
            opacity: 0.5
          }}
        />
      )}

      {/* --- Outgoing Edges --- */}
      {!selected.includes("is unique") && outgoing.length > 0 && (
        <Box sx={{ fontSize: "0.7rem", opacity: 0.7 }}>
          Outgoing Edges
        </Box>
      )}

      {!selected.includes("is unique") && outgoing.map((edge) => {
        const edgelabel = getEdgeLabel(edge);
        const label = `${edgelabel} → ${getTargetLabel(edge)}`;
        if (edgelabel === null) { return [] }
        return (
          <FormControlLabel
            key={edge.id}
            control={
              <Checkbox
                checked={selected.includes(edge.id)}
                onChange={() => toggle(edge.id)}
                sx={{ color: "white" }}
              />
            }
            label={label}
            sx={{
              color: "white",
              ml: 1,
              "&:hover": { backgroundColor: "#333" },
              borderRadius: "4px"
            }}
          />
        );
      })}

      {/* --- Incoming Edges --- */}
      {!selected.includes("is unique") && incoming.length > 0 && (
        <Box sx={{ fontSize: "0.7rem", marginTop: "6px", opacity: 0.7 }}>
          Incoming Edges
        </Box>
      )}

      {!selected.includes("is unique") && incoming.map((edge) => {
        const edgelabel = getEdgeLabel(edge);
        const label = `${getSourceLabel(edge)} → ${edgelabel}`;
        if (edgelabel === null) { return [] }
        return (
          <FormControlLabel
            key={edge.id}
            control={
              <Checkbox
                checked={selected.includes(edge.id)}
                onChange={() => toggle(edge.id)}
                sx={{ color: "white" }}
              />
            }
            label={label}
            sx={{
              color: "white",
              ml: 1,
              "&:hover": { backgroundColor: "#333" },
              borderRadius: "4px"
            }}
          />
        );
      })}
    </Paper>
    </ClickAwayListener>
  );
}
