      let a = 0, cx = 0, cy = 0;
      for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
        const [x0, y0] = pts[j];
        const [x1, y1] = pts[i];
        const cross = x0 * y1 - x1 * y0;
        a += cross;
        cx += (x0 + x1) * cross;
        cy += (y0 + y1) * cross;
      }
      a *= 0.5;
      if (Math.abs(a) < 1e-6) {
        const s = pts.reduce((acc, [x, y]) => [acc[0] + x, acc[1] + y], [0, 0]);
        return [s[0] / pts.length, s[1] / pts.length];
      }
