// utils/useDetachedWindowPortal.js
import { useEffect, useRef, useState } from "react";
import ReactDOM from "react-dom";

export default function useDetachedWindowPortal(
    open,
    title = "Graph Tool",
    featuresBase = "width=900,height=600,left=300,top=200"
) {
    const containerRef = useRef(null);
    const [externalWindow, setExternalWindow] = useState(null);
    const [ready, setReady] = useState(false); // 👈 add readiness flag

    useEffect(() => {
        if (!open) {

            setExternalWindow(null);
            setReady(false);
            return;
        }

        let newWin = null;

        const openOnOtherScreen = async () => {
            if ("getScreenDetails" in window) {
                try {
                    const details = await window.getScreenDetails();
                    const { currentScreen, screens } = details;

                    if (screens.length > 1) {
                        // 🪄 find any other screen than current
                        const targetScreen =
                            screens.find((s) => s.label !== currentScreen.label) || screens[1];

                        const features = `${featuresBase},left=${targetScreen.availLeft + 50},top=${targetScreen.availTop + 50
                            },width=${Math.min(targetScreen.width - 100, 1200)},height=${Math.min(
                                targetScreen.height - 100,
                                800
                            )}`;

                        newWin = window.open("", title, features);
                    }
                } catch (err) {
                    console.warn(
                        "Screen Enumeration API unavailable or not permitted:",
                        err
                    );
                }
            }

            // fallback → open normally on main screen
            if (!newWin) {
                newWin = window.open("", title, featuresBase);
            }
            if (!newWin) return;

            // 🖼️ basic setup
            newWin.document.title = title;
            newWin.document.body.style.margin = "0";
            newWin.document.body.style.background = "#0d0d0d";
            newWin.document.body.style.color = "white";
            newWin.document.body.style.overflow = "hidden";

            // ✅ ADD THIS LINE RIGHT HERE:
            newWin.onbeforeunload = () => {
                // tell React to update Clicker state when user closes detached window
                setExternalWindow(null);
                setReady(false);
                if (typeof window !== "undefined" && window.dispatchEvent) {
                    // optional custom event you can listen for in Clicker
                    window.dispatchEvent(new Event("detachedWindowClosed"));
                }
            };

            const meta = newWin.document.createElement("meta");
            meta.name = "viewport";
            meta.content = "width=device-width, initial-scale=1.0";
            newWin.document.head.appendChild(meta);

            // ✨ copy all styles (initial + dynamic)
            const copyStyles = () => {
                Array.from(document.styleSheets).forEach((sheet) => {
                    try {
                        if (sheet.href) {
                            if (
                                ![...newWin.document.styleSheets].some(
                                    (s) => s.href === sheet.href
                                )
                            ) {
                                const link = newWin.document.createElement("link");
                                link.rel = "stylesheet";
                                link.href = sheet.href;
                                newWin.document.head.appendChild(link);
                            }
                        } else if (sheet.cssRules) {
                            const style = newWin.document.createElement("style");
                            for (let rule of sheet.cssRules) {
                                style.appendChild(
                                    newWin.document.createTextNode(rule.cssText)
                                );
                            }
                            newWin.document.head.appendChild(style);
                        }
                    } catch {
                        /* ignore cross-origin sheets */
                    }
                });
            };
            copyStyles();

            // watch for new MUI/emotion style tags
            let lastUpdate = 0;
            const observer = new MutationObserver(() => {
                const now = Date.now();
                if (now - lastUpdate > 2) {
                    lastUpdate = now;
                    requestAnimationFrame(copyStyles);
                }
            });

            observer.observe(document.head, { childList: true, subtree: true });

            // create container and render portal
            // create container and render portal
            const container = newWin.document.createElement("div");
            newWin.document.body.appendChild(container);
            containerRef.current = container;
            setExternalWindow(newWin);

            // ✅ copy styles *first* (ensures MUI/Emotion CSS exists)
            // 🕒 wait until MUI/Emotion has injected its runtime <style> tags
            const waitForEmotion = async () => {
                const start = performance.now();
                while (
                    !document.querySelector('style[data-emotion]') &&
                    performance.now() - start < 1000 // give it up to 1 s
                ) {
                    await new Promise((r) => requestAnimationFrame(r));
                }
            };
            await waitForEmotion();

            // ✅ now safe to copy styles and mark ready
            copyStyles();
            setReady(true);

            const cleanup = () => {
                observer.disconnect();
                if (!newWin.closed) newWin.close();
                setExternalWindow(null);
                setReady(false);
            };


            return cleanup;
        };

        // open asynchronously
        let cleanup;
        openOnOtherScreen().then((fn) => {
            cleanup = fn;
        });

        return () => {
            if (cleanup) cleanup();
        };
    }, [open, title, featuresBase]);

    // ✅ re-render only when ready
    const portalFn =
        ready && containerRef.current && externalWindow
            ? (children) => ReactDOM.createPortal(children, containerRef.current)
            : null;

    return [portalFn, ready]; // 👈 return both portal and ready flag
}