// NodeChip.tsx
import React, { useState, useMemo } from "react";
import { Handle, Position, useReactFlow } from "reactflow";
import { Box, IconButton, Tooltip, Typography, Button } from "@mui/material";
import Visibility from "@mui/icons-material/Visibility";
import { useEffect } from "react";
import VisibilityOff from "@mui/icons-material/VisibilityOff";
import DirectionsCar from "@mui/icons-material/DirectionsCar";
import PedalBike from "@mui/icons-material/PedalBike";
import DirectionsBus from "@mui/icons-material/DirectionsBus";
import { useGraph } from "../components/GraphContext";
import { useTemplates } from "../components/TemplateContext";
import { Autocomplete, TextField, Chip } from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete"
import Popper from "@mui/material/Popper";
import AddIcon from "@mui/icons-material/Add";
import Badge from "@mui/material/Badge";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import SwapVertIcon from "@mui/icons-material/SwapVert";
import StraightIcon from '@mui/icons-material/Straight';
import LockIcon from '@mui/icons-material/Lock';
import LockOpenIcon from '@mui/icons-material/LockOpen';
import UnfoldMoreIcon from '@mui/icons-material/UnfoldMore';
import UnfoldLessIcon from '@mui/icons-material/UnfoldLess';

const CustomPopper = (props) => (
    <Popper
        {...props}
        modifiers={[
            {
                name: "width",
                enabled: true,
                phase: "beforeWrite",
                requires: ["computeStyles"],
                fn: ({ state }) => {
                    state.styles.popper.width = `${state.rects.reference.width}px`;
                },
            },
        ]}
    />
);

export default function NodeChip({ id, data }) {
    const { expandedNodeId, setExpandedNodeId, currentIndex, selectedNode, connectedNodes, selectedEdgeId, updateVisibility, updateProperty, deleteProperty, updateHelpers, nodes } = useGraph();
    const { addTemplateProperty, templatesRef, propertyOptions } = useTemplates();
    const PROHIBITED_KEYS = {
        lane: ["direction", "type"],                // already shown as icons
        traffic_light: ["status"],                    // if you have a vehicle node type
    };

    const [newKey, setNewKey] = React.useState("");
    const [newValue, setNewValue] = React.useState("");
    const [isLocked, setIsLocked] = React.useState(false);
    const [showInlineAdd, setShowInlineAdd] = useState(false);
    const rf = useReactFlow();

    const [dirtyFields, setDirtyFields] = useState({});

    const { label = id, properties = {}, helpers = {}, type: nodeKind } = data || {};
    const expanded = expandedNodeId === helpers.uuid;
    const color = useMemo(
        () => templatesRef.current?.[nodeKind]?.color || "#ccc",
        [templatesRef, nodeKind]
    );

    const selected = (selectedNode === null && selectedEdgeId === null) ? true :
        selectedNode ? selectedNode.data.helpers.uuid === data.helpers.uuid : false;
    // 🧭 Determine visibility for the current frame
    let isVisible = true; // default
    if (data.visibleAt) {
        isVisible = data.visibleAt[currentIndex];
    }



    useEffect(() => {

        if (!expandedNodeId) {
            // No node is expanded → reset FOV
            rf.fitView({ duration: 500 });
            return;
        }

        const node = rf.getNodes().find(
            (n) => n.data?.helpers?.uuid === expandedNodeId
        );

        if (!node) return;

        // When expanded, center and zoom to it
        rf.setCenter(
            node.position.x + (node.width || 0),
            node.position.y + (node.height || 0),
            {
                zoom: 2, // <== adjust this value to your desired FOV
                duration: 500,
            }
        );
    }, [expandedNodeId, rf]);

    // vehicle type (only for lane nodes)
    const VEHICLE_ORDER = ["VEHICLE", "BIKE", "BUS"];
    const vehicleKind = properties?.type || "VEHICLE";
    const cycleVehicle = () => {
        const idx = VEHICLE_ORDER.indexOf(vehicleKind);
        const next = VEHICLE_ORDER[(idx + 1) % VEHICLE_ORDER.length];
        updateProperty(helpers.uuid, "type", next)
    };


    const cycleComplete = (all = false) => {
        const next = !helpers.is_complete[currentIndex];  // toggles true/false

        // If switching from false → true, ask for confirmation
        if (next && all === true) {
            const confirmMsg = `Are you confirming that you have annotated all ${data.type}s in this scene?`;
            const ok = window.confirm(confirmMsg);

            if (!ok) return;  // user canceled → stop everything
        }

        // Update all nodes with the same type (except current)
        if (!all) {
            nodes.forEach(node => {
                if (node.data.type === data.type) {
                    updateHelpers(node.data.helpers.uuid, "is_complete", next);
                }
            });
        }
        if (all) {
            nodes.forEach(node => {
                if (node.data.type === data.type) {
                    const visibleFrames = Object.keys(node.data.visibleAt || {}).map(Number);
                    visibleFrames.forEach(ts => {
                        updateHelpers(node.data.helpers.uuid, "is_complete", next, ts);
                    });

                }
            });
        }

        // // Update the current helper
        // updateHelpers(helpers.uuid, "is_complete", next);

        // // Update all nodes with the same type (except current)
        // nodes.forEach(node => {
        //     if (node.data.type === data.type && node.data.helpers.uuid !== helpers.uuid) {
        //         updateHelpers(node.data.helpers.uuid, "is_complete", next);
        //     }
        // });
    };

    // status cycle logic for traffic_light nodes
    const STATUS_ORDER = ["red", "yellow", "green", "unknown"];

    let currentStatus = (nodeKind === "traffic_light" && properties?.status && properties?.status[currentIndex]) || "unknown"; // fallback if not defined

    // color & question mark
    const circleColor =
        currentStatus === "red"
            ? "red"
            : currentStatus === "yellow"
                ? "gold"
                : currentStatus === "green"
                    ? "limegreen"
                    : "grey";
    const showQuestionMark = currentStatus === "unknown";

    // click handler: cycle status
    const cycleTrafficLight = () => {
        const idx = STATUS_ORDER.indexOf(currentStatus);
        const next = STATUS_ORDER[(idx + 1) % STATUS_ORDER.length];
        let status = properties?.status || "unknown"
        status[currentIndex] = next
        updateProperty(data.helpers.uuid, "status", next)

    };

    const VehicleIcon = vehicleKind === "BIKE" ? PedalBike : vehicleKind === "BUS" ? DirectionsBus : DirectionsCar;

    const updateLaneDirectionAndEdges = (nextDir) => {
        updateProperty(data.helpers.uuid, "direction", nextDir)
    };

    const visiblePropsCount = Object.keys(properties || {}).length;
    const highlighted = selected || (connectedNodes && connectedNodes.includes(id))

    // ✅ Memoize computed sx blocks
    const chipBoxSx = useMemo(() => ({
        zIndex: expanded ? 9999 : 5,
        borderRadius: "10px",
        px: 0,
        py: 0,
        minWidth: expanded ? "140px" : "",
        maxWidth: "150px",
        justifyContent: "center",
        boxShadow: selected && selectedNode !== null
            ? `0 0 8px 3px white, 0 2px 6px rgba(0,0,0,0.25)`
            : "0 2px 6px rgba(0,0,0,0.15)",
        border: selected ? `2px solid ${color}` : "1px solid rgba(0,0,0,0.05)",
        backgroundColor: highlighted ? color : "grey",
        cursor: "grab",
        opacity: highlighted ? 1 : 0.35,
        transition: "box-shadow 0.25s ease, border 0.25s ease, opacity 0.25s ease",
    }), [expanded, selected, selectedNode, color, highlighted]);
    return (
        <Badge
            badgeContent={visiblePropsCount || "0"}
            color="primary"
            overlap="circular"
            anchorOrigin={{ vertical: "top", horizontal: "right" }}
            sx={{
                "& .MuiBadge-badge": {
                    fontSize: "0.35rem",
                    width: 2,
                    height: 8,
                    right: 2,
                    top: 1,
                    opacity: highlighted ? 1 : 0.35,
                    backgroundColor: highlighted ? "#0d47a1" : "grey",
                    color: "white",
                    zIndex: 9999,
                    p: 0,
                    boxShadow: "0 1px 2px rgba(0,0,0,0.25)",
                },
            }}
        >
            <Box
                className="chip-drag"
                onDoubleClick={(e) => {
                    e.stopPropagation();

                    const nextId = expanded ? null : helpers.uuid;
                    setExpandedNodeId(nextId);


                }}
                sx={chipBoxSx}
            >


                <Box sx={{
                    pr: 0.25,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    gap: 0.75,
                }}>

                    {label !== "Ego" && (

                        <IconButton
                            size="small"
                            className="nodrag nopan"
                            onPointerDown={(e) => e.stopPropagation()}
                            onClick={(e) => {
                                e.stopPropagation();
                                cycleComplete(false);
                            }}
                            onContextMenu={(e) => {
                                e.stopPropagation();
                                cycleComplete(true);
                            }}
                            aria-label="Cycle completeness"
                            sx={{
                                mx: 0,
                                p: 0.2,
                                borderRadius: 9999,
                                bgcolor: "transparent",
                                "&:hover": { bgcolor: "rgba(255,255,255,0.9)" },
                                boxShadow: "0",
                                "& .MuiSvgIcon-root": { fontSize: "10px", color: "black" },
                            }}
                        >
                            {helpers.is_complete && helpers?.is_complete[currentIndex] ? <LockIcon /> : <LockOpenIcon />}
                        </IconButton>

                    )}
                    {/* LABEL (left) */}
                    <Typography
                        variant="caption"
                        noWrap
                        title={label}
                        sx={{
                            fontWeight: 400,
                            lineHeight: 1,
                            color: "#111",
                            ml: 0.5,
                            flex: 1,
                            fontSize: "8px",
                            textAlign: "left",
                            textDecoration: isVisible ? "none" : "line-through",
                        }}
                    >
                        {label}
                    </Typography>
                    {/* ICONS (right) */}
                    <Box sx={{ display: "flex", alignItems: "center", pr: 0.25 }}>

                        {/* Expand / collapse properties (same as double-click) */}
                        <Tooltip title={expanded ? "Collapse" : "Expand properties"}>
                            <IconButton
                                size="small"
                                className="nodrag nopan"
                                onPointerDown={(e) => e.stopPropagation()}
                                onClick={(e) => {
                                    e.stopPropagation();
                                    setExpandedNodeId(expanded ? null : helpers.uuid);
                                }}
                                aria-label={expanded ? "Collapse node" : "Expand node"}
                                sx={{
                                    mx: 0.1,
                                    p: 0.2,
                                    borderRadius: 9999,
                                    bgcolor: expanded ? "rgba(255,255,255,0.95)" : "rgba(255,255,255,0.7)",
                                    "&:hover": { bgcolor: "rgba(255,255,255,0.9)" },
                                    boxShadow: "0 1px 2px rgba(0,0,0,0.15)",
                                    "& .MuiSvgIcon-root": { fontSize: "10px", color: "black" },
                                }}
                            >
                                {expanded ? <UnfoldLessIcon /> : <UnfoldMoreIcon />}
                            </IconButton>
                        </Tooltip>

                        {/* Visibility */}
                        <Tooltip title={isVisible ? "Hide" : "Show"}>
                            <IconButton
                                size="small"
                                className="nodrag nopan"
                                onPointerDown={(e) => e.stopPropagation()}
                                onClick={(e) => {
                                    e.stopPropagation();
                                    updateVisibility(data.helpers.uuid, !isVisible);
                                }}
                                aria-label={isVisible ? "Hide" : "Show"}
                                sx={{
                                    mx: 0.1,
                                    p: 0.2,
                                    borderRadius: 9999,
                                    bgcolor: "rgba(255,255,255,0.7)",
                                    "&:hover": { bgcolor: "rgba(255,255,255,0.9)" },
                                    boxShadow: "0 1px 2px rgba(0,0,0,0.15)",
                                    "& .MuiSvgIcon-root": { fontSize: "10px", color: "black" },
                                }}
                            >
                                {isVisible ? <Visibility /> : <VisibilityOff />}
                            </IconButton>
                        </Tooltip>

                        {/* Vehicle cycler — only for lane nodes */}
                        {nodeKind === "lane" && (
                            <>
                                {/* Direction indicator */}
                                <Tooltip title={`Direction: ${properties.direction || "same"}`}>
                                    <IconButton
                                        size="small"
                                        className="nodrag nopan"
                                        onPointerDown={(e) => e.stopPropagation()}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            const nextDir = properties.direction === "opposite" ? "same" : "opposite";
                                            updateLaneDirectionAndEdges(nextDir);
                                        }}
                                        aria-label="Toggle direction"
                                        sx={{
                                            mx: 0.1,
                                            p: 0.2,
                                            borderRadius: 9999,
                                            bgcolor: "rgba(255,255,255,0.7)",
                                            "&:hover": { bgcolor: "rgba(255,255,255,0.9)" },
                                            boxShadow: "0 1px 2px rgba(0,0,0,0.15)",
                                            "& .MuiSvgIcon-root": { fontSize: "10px", color: "black" },
                                        }}
                                    >
                                        {properties.direction === "opposite" ? (
                                            <SwapVertIcon />
                                        ) : (
                                            <StraightIcon />
                                        )}
                                    </IconButton>
                                </Tooltip>

                            </>
                        )}

                        {/* Traffic Light status indicator */}
                        {nodeKind === "traffic_light" && (
                            <Tooltip title={`Status: ${currentStatus}`}>
                                <IconButton
                                    size="small"
                                    className="nodrag nopan"
                                    onPointerDown={(e) => e.stopPropagation()}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        cycleTrafficLight();
                                    }}
                                    aria-label="Cycle traffic light status"
                                    sx={{
                                        mx: 0.1,
                                        p: 0.02,
                                        borderRadius: "50%",
                                        bgcolor: "rgba(255,255,255,0.7)",
                                        "&:hover": { bgcolor: "rgba(255,255,255,0.9)" },
                                        boxShadow: "0 1px 2px rgba(0,0,0,0.15)",
                                        display: "flex",
                                        alignItems: "center",
                                        justifyContent: "center",
                                        width: 14,
                                        height: 14,
                                    }}
                                >
                                    <Box
                                        sx={{
                                            width: 10,
                                            height: 10,
                                            borderRadius: "50%",
                                            backgroundColor: circleColor,
                                            display: "flex",
                                            alignItems: "center",
                                            justifyContent: "center",
                                            fontSize: "8px",
                                            color: "white",
                                            fontWeight: "bold",
                                        }}
                                    >
                                        {showQuestionMark ? "?" : ""}
                                    </Box>
                                </IconButton>
                            </Tooltip>
                        )}

                        {/* Vehicle cycler — only for lane nodes */}
                        {nodeKind === "lane" && (

                            <IconButton
                                size="small"
                                className="nodrag nopan"
                                onPointerDown={(e) => e.stopPropagation()}
                                onClick={(e) => {
                                    e.stopPropagation();
                                    cycleVehicle();
                                }}
                                aria-label="Cycle vehicle type"
                                sx={{
                                    mx: 0.1,
                                    p: 0.2,
                                    borderRadius: 9999,
                                    bgcolor: "rgba(255,255,255,0.7)",
                                    "&:hover": { bgcolor: "rgba(255,255,255,0.9)" },
                                    boxShadow: "0 1px 2px rgba(0,0,0,0.15)",
                                    "& .MuiSvgIcon-root": { fontSize: "10px", color: "black" },
                                }}
                            >
                                <VehicleIcon />
                            </IconButton>

                        )}

                    </Box>
                </Box>



                {expanded && (
                    <Box>
                        <Box
                            sx={{
                                backgroundColor: "#f5f5f59b",

                                fontSize: "7px", p: 1, pt: 0, pb: 2,
                            }}
                        >
                            {Object.entries(properties || {})
                                .filter(([key]) => !PROHIBITED_KEYS[nodeKind]?.includes(key))
                                .map(([key, value]) => {
                                    // Get candidate values
                                    const templateVals =
                                        templatesRef.current[nodeKind]?.defaultProperties?.find(
                                            (p) => p.key === key
                                        )?.values || [];
                                    const propVals = propertyOptions[nodeKind]?.[key] || [];
                                    const options = Array.from(new Set([...templateVals, ...propVals]));
                                    const isDirty = dirtyFields[key] || false;
                                    return (
                                        <Box
                                            key={key}
                                            sx={{
                                                display: "flex",
                                                alignItems: "center",
                                                mb: 0,

                                                gap: 0.1,
                                                width: "100%",
                                            }}
                                        >
                                            <Box sx={{ flex: 1, mt: 2. }}>
                                                <Autocomplete
                                                    disableClearable
                                                    openOnFocus
                                                    freeSolo
                                                    disablePortal={false}
                                                    PopperComponent={CustomPopper}
                                                    PopperProps={{ disablePortal: false }}
                                                    options={options}
                                                    value={
                                                        Array.isArray(properties[key])
                                                            ? properties[key][currentIndex]
                                                            : typeof properties[key] === 'object' && properties[key] !== null
                                                                ? properties[key][currentIndex]
                                                                : properties[key] || ''
                                                    }
                                                    onMouseDown={(e) => e.stopPropagation()}
                                                    onClick={(e) => e.stopPropagation()}
                                                    sx={{
                                                        height: 18,
                                                        fontSize: "0.45rem",
                                                        pl: 0,
                                                        backgroundColor: "#fff",
                                                        borderRadius: "6px",
                                                        borderColor: 'white',
                                                        boxShadow: "0 1px 3px rgba(0, 0, 0, 0.15)",

                                                        "& .MuiAutocomplete-inputRoot": {
                                                            fontSize: "0.45rem",
                                                            padding: "0 1px 0 1px",
                                                            display: "flex",
                                                            alignItems: "center",
                                                            justifyContent: "flex-start",
                                                            minHeight: "unset",
                                                            textAlign: "left",
                                                            color: "black",
                                                            backgroundColor: "#fff",
                                                            borderRadius: "6px",
                                                        },

                                                        // --- ensure the outline background isn’t covered ---

                                                        "& .MuiAutocomplete-input": {
                                                            padding: "2px 2px !important",
                                                            margin: 0,
                                                            textAlign: "left",
                                                        },

                                                        "& .MuiOutlinedInput-root": {
                                                            padding: 0,
                                                            height: 20,
                                                            minHeight: "unset",
                                                            backgroundColor: "#fff",
                                                            borderRadius: "6px",
                                                            boxShadow: "inset 0 0 1px rgba(0,0,0,0.1)",
                                                        },

                                                        "& .MuiOutlinedInput-root.Mui-focused .MuiOutlinedInput-notchedOutline": {
                                                            borderColor: 'white',
                                                            borderWidth: "1px",
                                                            boxShadow: "0 0 3px rgba(25,118,210,0.3)",
                                                            left: "0px",
                                                        },

                                                        "& .MuiChip-root": {
                                                            height: 16,
                                                            fontSize: "0.55rem",
                                                            margin: "0 1px",
                                                            borderRadius: "4px",
                                                            backgroundColor: "#da1b1bff",
                                                            "& .MuiChip-label": { padding: "0 3px" },
                                                            "& .MuiChip-deleteIcon": {
                                                                fontSize: "0.4rem",
                                                                marginRight: "-3px",
                                                            },
                                                        },

                                                        "& .MuiAutocomplete-option": {
                                                            fontSize: "0.65rem",
                                                            padding: "2px 6px",
                                                            borderColor: 'white',
                                                            minHeight: "20px",
                                                            backgroundColor: "#fff",
                                                            "&:hover": { backgroundColor: "#f0f0f0" },
                                                        },

                                                        "& .MuiInputLabel-root": {
                                                            position: "absolute",
                                                            top: "-7.5px",
                                                            left: "0px",
                                                            backgroundColor: 'transparent', // ⬅️ important: do NOT fill white here
                                                            fontSize: "0.4rem",
                                                            transform: "none",
                                                            transition: "none",
                                                            pointerEvents: "none",
                                                            color: "#241f1fff",
                                                        },

                                                        '& .MuiOutlinedInput-notchedOutline': {
                                                            borderColor: 'white',
                                                            borderWidth: '0.05rem',
                                                            pointerEvents: 'none',
                                                        },

                                                    }}

                                                    renderTags={() => null} // disable default MUI tags
                                                    renderInput={(params) => (
                                                        <TextField
                                                            {...params}
                                                            label={key}
                                                            placeholder="Type and press Enter"
                                                            size="small"

                                                            onKeyDown={async (e) => {
                                                                const pressedKey = e.key;

                                                                // 🟡 Mark dirty on any normal key press (not Enter or Tab)
                                                                if (pressedKey !== "Enter") {
                                                                    setDirtyFields((prev) => ({ ...prev, [key]: true }));
                                                                    return; // stop here — don't trigger save logic
                                                                }

                                                                // ✅ Save on Enter
                                                                if (pressedKey === "Enter" && e.target.value.trim()) {
                                                                    e.preventDefault();
                                                                    const typed = e.target.value.trim();

                                                                    updateProperty(helpers.uuid, key, typed)


                                                                    // Save to Supabase if new
                                                                    const knownValues =
                                                                        templatesRef.current[nodeKind]?.defaultProperties?.find(
                                                                            (p) => p.key === key
                                                                        )?.values || [];

                                                                    if (!knownValues.includes(typed)) {
                                                                        await addTemplateProperty(nodeKind, key, [typed]);
                                                                    }

                                                                    // ✅ Mark clean again
                                                                    setDirtyFields((prev) => ({ ...prev, [key]: false }));
                                                                }
                                                            }}
                                                            InputProps={{
                                                                ...params.InputProps,
                                                                startAdornment: null,
                                                                endAdornment: (

                                                                    <>
                                                                        {properties[key] && (
                                                                            <Box sx={{ display: "flex", alignItems: "center", pr: 0.5 }}>
                                                                                <CheckCircleIcon
                                                                                    sx={{
                                                                                        fontSize: "12px",
                                                                                        color: isDirty ? "#aaa" : "green",
                                                                                        opacity: 0.9,
                                                                                        transition: "color 0.2s ease, transform 0.2s ease",
                                                                                        transform: isDirty ? "scale(0.9)" : "scale(1)",
                                                                                    }}
                                                                                />
                                                                            </Box>
                                                                        )}
                                                                        {params.InputProps.endAdornment}
                                                                    </>
                                                                ),
                                                            }}
                                                        />
                                                    )}

                                                />
                                            </Box>

                                            {/* 🗑️ Delete icon */}
                                            <IconButton
                                                size="small"
                                                onMouseDown={(e) => e.stopPropagation()}
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    deleteProperty(helpers.uuid, key);   // uuid must come from n.data.helpers.uuid
                                                }}

                                                sx={{
                                                    p: 0.3,
                                                    mt: 2.,
                                                    ml: 0.5,
                                                    bgcolor: "rgba(255, 255, 255, 0.46)",
                                                    "&:hover": { bgcolor: "rgba(255,255,255,0.9)" },
                                                    boxShadow: 0,
                                                }}
                                            >
                                                <DeleteIcon sx={{ fontSize: "10px", color: "black" }} />
                                            </IconButton>
                                        </Box>
                                    );
                                })}
                            {showInlineAdd && (
                                <Box
                                    sx={{
                                        gap: 0.5,
                                        alignItems: "center",
                                        width: "100%",
                                        mt: 1,
                                        backgroundColor: "white",
                                        opacity: 1,
                                        p: 0.5,
                                        borderRadius: 2,
                                        boxShadow: "inset 0 0 2px rgba(0,0,0,0.1)",
                                    }}
                                >
                                    <TextField
                                        placeholder="Property key"
                                        size="small"
                                        value={newKey}
                                        onChange={(e) => setNewKey(e.target.value)}
                                        sx={{
                                            flex: 1,
                                            fontSize: "0.4rem",
                                            mb: 0.2,
                                            width: "100%",
                                            borderColor: "blue",
                                            backgroundColor: { color }, // 👈 textfield background
                                            input: { color: "black" }, // 👈 input text color
                                        }}
                                        inputProps={{ style: { fontSize: "0.4rem", padding: 2 } }}
                                    />
                                    <TextField
                                        placeholder="Default value"
                                        size="small"
                                        value={newValue}
                                        onChange={(e) => setNewValue(e.target.value)}
                                        sx={{
                                            flex: 1,
                                            fontSize: "0.4rem",
                                            width: "100%",
                                            backgroundColor: "color",
                                            input: { color: "black" },
                                        }}
                                        inputProps={{ style: { fontSize: "0.4rem", padding: 2 } }}
                                    />
                                    <Box sx={{ display: "flex", alignItems: "center" }}>
                                        <input
                                            type="checkbox"
                                            checked={isLocked}
                                            onChange={(e) => setIsLocked(e.target.checked)}
                                            style={{ marginRight: "2px", height: "10px" }}
                                        />
                                        <Typography variant="body2" sx={{ fontSize: "0.3rem", color: "black" }}>
                                            Locked
                                        </Typography>
                                    </Box>
                                    <Box
                                        sx={{
                                            display: "flex",
                                            minWidth: 0,
                                            gap: 0.5,
                                            alignItems: "center",
                                            width: "100%",
                                            mt: 0.3,
                                            backgroundColor: "#bd4545ff",
                                            p: 0.5,
                                            borderRadius: 2,
                                            boxShadow: "inset 0 0 2px rgba(0,0,0,0.1)",
                                        }}
                                    >
                                        <Button
                                            size="small"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                if (!newKey.trim()) return;
                                                addTemplateProperty(nodeKind, newKey.trim(), [newValue.trim()], isLocked);
                                                setNewKey("");
                                                setNewValue("");
                                                setShowInlineAdd(false);
                                            }}
                                            sx={{
                                                p: 0,
                                                flex: 1,
                                                minWidth: 0,
                                                bgcolor: "color", // ✅ themed background
                                                color: "black",   // ✅ black font
                                                fontSize: "4px",
                                                "&:hover": { bgcolor: "#ccc" },
                                            }}
                                        >
                                            add
                                        </Button>
                                        <Button
                                            size="small"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                setShowInlineAdd(false);
                                                setNewKey("");
                                                setNewValue("");
                                            }}
                                            sx={{
                                                p: 0,
                                                flex: 1,
                                                bgcolor: "color",
                                                color: "black",
                                                fontSize: "4px",
                                                "&:hover": { bgcolor: "#ccc" },
                                            }}
                                        >
                                            cancel
                                        </Button>
                                    </Box>
                                </Box>
                            )}

                        </Box>
                        <Box
                            sx={{
                                backgroundColor: "white",
                                borderBottomLeftRadius: 8,
                                borderBottomRightRadius: 8,
                                fontSize: "7px", p: 1, pt: 0, mt: 0, minWidth: "110px"
                            }}
                        >
                            {/* Suggested properties not yet added */}
                            <Typography
                                sx={{
                                    fontSize: "6px",
                                    color: "#222",
                                    pt: 0.5,
                                    textAlign: "left",  // <-- this is what you need
                                    width: "100%",       // optional: ensures it spans the row
                                    display: "block",    // ensures textAlign applies properly
                                }}
                            >
                                Add properties
                            </Typography>
                            <Box sx={{ display: "flex", flexWrap: "wrap", gap: 0.3, }}>
                                {(templatesRef.current[nodeKind]?.defaultProperties || [])
                                    .filter(
                                        (p) => !Object.keys(properties || {}).includes(p.key)
                                    )
                                    .map((p) => (
                                        <Chip
                                            key={p.key}
                                            label={p.key}
                                            size="small"
                                            sx={{
                                                fontSize: "0.4rem",
                                                height: 12,
                                                backgroundColor: color,
                                                "&:hover": {
                                                    backgroundColor: "#cfd8dc",
                                                    cursor: "pointer",
                                                },
                                            }}
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                updateProperty(helpers.uuid, p.key, "")

                                            }}
                                        />
                                    ))}
                                <IconButton
                                    size="small"
                                    sx={{
                                        px: 0.2,
                                        height: 12,
                                        backgroundColor: "#d9d8d8ff",
                                        color: "#111",
                                        "&:hover": {
                                            backgroundColor: "#f0f0f0",
                                            cursor: "pointer",
                                        },
                                    }}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        setShowInlineAdd((v) => !v);
                                    }}
                                >
                                    <AddIcon sx={{ fontSize: "9px" }} />
                                </IconButton>
                            </Box>
                        </Box> </Box>
                )}

                {/* Hidden handles if you need them */}
                <Handle
                    type="target"
                    position={Position.Top}
                />
                <Handle
                    type="source"
                    position={Position.Bottom}
                />
            </Box></Badge >
    );
}