export function connectLaneNeighbors(newNode, nodes, visibleAt, intersectVisible) {
  if (newNode.data.type !== "lane") return [];

  const { left_neighbors = [], right_neighbors = [] } = newNode.data.helpers;
  const dirA = newNode.data.properties.direction;
  const edges = [];

  const connect = (uuid, baseSideLabel) => {
    const neighbor = nodes.find(
      (n) => String(n.data?.helpers?.uuid) === String(uuid)
    );
    if (!neighbor) return;

    if (neighbor.data.type !== "lane") return;

    const dirB = neighbor.data.direction || "same";

    const commonVisible = intersectVisible(
      visibleAt,
      Object.keys(neighbor.data?.visibleAt).map(Number)
    );
    if (!commonVisible.length) return;

    // 🔄 Flip the relation if directions differ
    const flip = dirA !== dirB;

    // baseSideLabel = "left" or "right"
    const finalSideLabel =
      flip
        ? (baseSideLabel === "left" ? "right" : "left")
        : baseSideLabel;

    const label = `is ${finalSideLabel} of`;

    edges.push({
      source: newNode.id,
      target: neighbor.id,
      type: "static",       // or dynamic
      category: "location", // location | occlusion | impact | regulation
      label: label,
      description: null,
      rule: null,
      targets: null
    });
  };

  // A.left_neighbors → normally A is right of B
  left_neighbors.forEach((uuid) => connect(uuid, "right"));

  // A.right_neighbors → normally A is left of B
  right_neighbors.forEach((uuid) => connect(uuid, "left"));

  return edges;
}