import React, { useState, useRef, useCallback } from 'react';
import { Box } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import { useTemplates } from '../components/TemplateContext';

// halfExtent: metres shown from the ego to the nearer edge of the map (smaller = more zoomed in).
export default function TopDown2D({ laneData, pose, lanes, selectedTElement, halfExtent = 35 }) {
  // Ego heading in the world frame: pose.rotation is world_from_ego and the ego x-axis points forward,
  // so the forward direction is the rotation's first column.
  const R = pose.rotation;
  const heading = R ? Math.atan2(R[1][0], R[0][0]) : 0;
  // Rotate the map around the ego so the driving direction always points up
  // (world y is flipped in SVG, so a heading of `heading` points at -heading degrees on screen).
  const headingUpDeg = (heading * 180) / Math.PI - 90;

  // Map colours follow the node-type colours used in the graph and on the images.
  const theme = useTheme();
  const { templatesRef } = useTemplates();
  const nodeColor = (type, fallback) => templatesRef.current?.[type]?.color || fallback;
  const colors = {
    intersection: nodeColor("intersection", "#e55b5b"),
    crossing: nodeColor("crossing", "#dae55b"),
    trafficLight: nodeColor("traffic_light", "#e5b05b"),
    bike: nodeColor("bicycle", "#5be59b"),
    ego: theme.palette.primary.main,
    hover: theme.palette.secondary.main,
  };
  const segments = Object.values(laneData.lane_segments || {});
  const pedcross = Object.values(laneData.pedestrian_crossings || {});
  const area = Object.values(laneData.drivable_areas || {});

  // Visible extent around the ego (metres in each direction).
  // The visible area follows the box's aspect ratio so the map fills the whole box (no square crop);
  // the shorter side spans 2 * halfExtent metres.
  const [boxSize, setBoxSize] = useState({ w: 1, h: 1 });
  const boxObserverRef = useRef(null);
  const boxRef = useCallback((el) => {
    if (boxObserverRef.current) { boxObserverRef.current.disconnect(); boxObserverRef.current = null; }
    if (!el) return;
    let raf = 0;
    const obs = new ResizeObserver(([entry]) => {
      const { width: w, height: h } = entry.contentRect;
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        if (w > 0 && h > 0) setBoxSize(prev => (prev.w === w && prev.h === h ? prev : { w, h }));
      });
    });
    obs.observe(el);
    boxObserverRef.current = obs;
  }, []);
  const unitsPerPx = (2 * halfExtent) / Math.max(1, Math.min(boxSize.w, boxSize.h));
  const width = boxSize.w * unitsPerPx;
  const height = boxSize.h * unitsPerPx;

  // Define ego position
  const egoX = pose.translation[0];
  const egoY = pose.translation[1];

  // Pan/drag state
  const [mapOffset, setMapOffset] = useState({ x: 0, y: 0 });
  const [dragging, setDragging] = useState(false);
  const dragRef = useRef(null);
  const svgRef = useRef(null);

  const anyConnected = lanes.some(
    ls => ls.topoTL.includes(selectedTElement?.id)
  );

  // Drag to pan: the map follows the pointer 1:1 (screen pixels are converted to map units),
  // and the drag continues if the pointer leaves the map. Double-click re-centres on the ego.
  const handlePointerDown = (e) => {
    if (e.button !== 0) return;
    const ctm = svgRef.current?.getScreenCTM();
    dragRef.current = { x: e.clientX, y: e.clientY, unitsPerPx: ctm && ctm.a ? 1 / ctm.a : 1 };
    e.currentTarget.setPointerCapture(e.pointerId);
    setDragging(true);
  };
  const handlePointerMove = (e) => {
    const d = dragRef.current;
    if (!d) return;
    const dx = (e.clientX - d.x) * d.unitsPerPx;
    const dy = (e.clientY - d.y) * d.unitsPerPx;
    d.x = e.clientX;
    d.y = e.clientY;
    setMapOffset(o => ({ x: o.x - dx, y: o.y - dy }));
  };
  const handlePointerUp = () => {
    dragRef.current = null;
    setDragging(false);
  };

  // Adjust viewBox for panning and centre on the ego
  const viewX = egoX - width / 2 + mapOffset.x;
  const viewY = -egoY - height / 2 + mapOffset.y;
  const viewBox = `${viewX} ${viewY} ${width} ${height}`;


  return (
    <Box ref={boxRef} sx={{ width: "100%", height: "100%", overflow: "hidden" }}>

      <svg
        ref={svgRef}
        tabIndex={0}
        width="100%"
        height="100%"
        style={{ overflow: "hidden", background: "transparent", display: "block", cursor: dragging ? "grabbing" : "grab", outline: "none", touchAction: "none" }}
        viewBox={viewBox}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={handlePointerUp}
        onDoubleClick={() => setMapOffset({ x: 0, y: 0 })}
      >
        <defs>
          <clipPath id="map-clip">
            <rect x={viewX} y={viewY} width={width} height={height} />
          </clipPath>
        </defs><g clipPath="url(#map-clip)">
          <g transform={`rotate(${headingUpDeg}, ${egoX}, ${-egoY})`}>
            {area.map((seg, idx) => (
              <polygon
                key={idx}
                points={seg.area_boundary.map(pt => `${pt.x},${-pt.y}`).join(" ")}
                fill="#6B7384"
                opacity="0.35"

              />
            ))}
            {/* Lane Segments group for hover styling */}
            <g className="lane-segment">
              {segments.map((ls, idx) => {
                const classNameLeft = [
                  'lane-segment left',
                  !anyConnected && ls.left_lane_mark_type.includes('WHITE') ? 'white' : '',
                  !anyConnected && ls.left_lane_mark_type.includes('YELLOW') ? 'yellow' : '',
                  !anyConnected && ls.left_lane_mark_type.includes('BLUE') ? 'blue' : '',
                  !anyConnected && ls.left_lane_mark_type.includes('DASH') && !ls.left_lane_mark_type.includes('DASH_SOLID') ? 'dashed' : '',
                  !anyConnected && ls.left_lane_mark_type.includes('DASH_SOLID') ? 'dsolid' : '',
                  !anyConnected && ls.left_lane_mark_type.includes('DOUBLE') ? 'double' : '',
                  !anyConnected && ls.left_lane_mark_type.includes('UNKNOWN') ? 'unknown' : '',
                  !anyConnected && ls.left_lane_mark_type.includes('NONE') ? 'none' : '',
                ].filter(Boolean).join(' ');

                const classNameRight = [
                  'lane-segment right',
                  !anyConnected && ls.right_lane_mark_type.includes('WHITE') ? 'white' : '',
                  !anyConnected && ls.right_lane_mark_type.includes('YELLOW') ? 'dashed' : '',
                  !anyConnected && ls.right_lane_mark_type.includes('BLUE') ? 'blue' : '',
                  !anyConnected && ls.right_lane_mark_type.includes('DASH') && !ls.right_lane_mark_type.includes('DASH_SOLID') ? 'dashed' : '',
                  !anyConnected && ls.right_lane_mark_type.includes('DASH_SOLID') ? 'dsolid' : '',
                  !anyConnected && ls.right_lane_mark_type.includes('DOUBLE') ? 'double' : '',
                  !anyConnected && ls.right_lane_mark_type.includes('UNKNOWN') ? 'unknown' : '',
                  !anyConnected && ls.right_lane_mark_type.includes('NONE') ? 'none' : '',
                ].filter(Boolean).join(' ');

                const left0 = ls.left_lane_boundary[0];
                const right0 = ls.right_lane_boundary[0];
                const pos = {
                  x: (left0.x + right0.x) / 2,
                  y: (left0.y + right0.y) / 2
                };
                const left1 = ls.left_lane_boundary[1];
                const dx = left1.x - left0.x;
                const dy = left1.y - left0.y;
                const heading = Math.atan2(dy, dx);

                // Compute polygon points for all lanes
                const polygonPoints = [
                  ...ls.left_lane_boundary,
                  ...ls.right_lane_boundary.slice().reverse()
                ];

                return (
                  <g key={idx} >
                    <polygon
                      className="lane-polygon"
                      points={polygonPoints.map(pt => `${pt.x},${-pt.y}`).join(" ")}
                      fill={ls.lane_type === "BIKE" && !anyConnected ? colors.bike : ls.is_intersection ? colors.intersection : "none"}
                      stroke="none"
                      pointerEvents="all"
                      opacity={ls.lane_type === "BIKE" ? 0.3 : ls.is_intersection ? 0.3 : undefined}
                    />
                    {ls.lane_type === "BIKE" && !anyConnected && (
                      <g transform={`translate(${pos.x},${-pos.y}) rotate(${(-heading * 180 / Math.PI + 90)}) scale(0.015)`} fill="white">
                        <g transform="translate(-40,-90)">
                          <path
                            d="M 71.194 32.312 c -2.886 0 -5.612 0.673 -8.058 1.84 l -3.668 -6.37 l 3.351 -5.445 c 0.282 -0.458 0.294 -1.032 0.032 -1.501 c -0.263 -0.469 -0.758 -0.76 -1.295 -0.76 h -8.423 c -0.819 0 -1.484 0.664 -1.484 1.484 s 0.664 1.484 1.484 1.484 h 5.768 l -1.988 3.231 H 32.346 l -0.55 -1.006 h 1.233 c 0.82 0 1.484 -0.664 1.484 -1.484 s -0.664 -1.484 -1.484 -1.484 H 21.825 c -0.82 0 -1.484 0.664 -1.484 1.484 s 0.664 1.484 1.484 1.484 h 6.589 l 1.311 2.398 l -3.357 6.247 c -2.317 -1.022 -4.872 -1.6 -7.562 -1.6 C 8.437 32.312 0 40.749 0 51.119 c 0 10.369 8.437 18.806 18.806 18.806 c 9.869 0 17.97 -7.646 18.731 -17.322 h 5.213 v 2.118 h -2.331 c -0.82 0 -1.484 0.664 -1.484 1.484 s 0.664 1.484 1.484 1.484 h 6.516 c 0.819 0 1.484 -0.664 1.484 -1.484 s -0.664 -1.484 -1.484 -1.484 h -1.218 v -3.204 L 57.74 30.725 l 2.82 4.898 c -4.93 3.394 -8.172 9.071 -8.172 15.495 c 0 10.369 8.437 18.806 18.807 18.806 C 81.563 69.924 90 61.488 90 51.119 C 90 40.749 81.563 32.312 71.194 32.312 z M 31.424 30.773 l 10.309 18.862 h -4.196 c -0.472 -6.001 -3.765 -11.212 -8.559 -14.31 L 31.424 30.773 z M 34.57 49.635 H 21.287 l 6.286 -11.697 C 31.444 40.521 34.114 44.76 34.57 49.635 z M 18.806 66.957 c -8.734 0 -15.839 -7.106 -15.839 -15.839 c 0 -8.734 7.106 -15.839 15.839 -15.839 c 2.183 0 4.264 0.444 6.158 1.246 l -7.465 13.891 c -0.247 0.46 -0.234 1.015 0.033 1.463 c 0.268 0.448 0.751 0.722 1.273 0.722 H 34.57 C 33.819 60.641 27.039 66.957 18.806 66.957 z M 44.27 48.092 L 33.967 29.241 h 21.204 L 44.27 48.092 z M 71.194 66.957 c -8.734 0 -15.84 -7.106 -15.84 -15.839 c 0 -5.326 2.651 -10.037 6.694 -12.909 l 7.86 13.649 c 0.274 0.477 0.774 0.744 1.286 0.744 c 0.251 0 0.506 -0.064 0.739 -0.198 c 0.711 -0.409 0.954 -1.315 0.546 -2.025 l -7.861 -13.652 c 2.006 -0.92 4.228 -1.447 6.576 -1.447 c 8.733 0 15.839 7.106 15.839 15.839 C 87.033 59.852 79.927 66.957 71.194 66.957 z"
                            fill="white"
                            stroke="none"
                            strokeWidth="1"
                            strokeLinecap="round"
                            strokeLinejoin="miter"
                          />
                        </g>
                      </g>
                    )}
                    {ls.lane_type === "BUS" && (
                      <g transform={`translate(${pos.x},${-pos.y}) rotate(${(-heading * 180 / Math.PI + 90)}) scale(0.015)`} fill="white">
                        <g transform="translate(-40,-90)">
                          <g transform="translate(8,0) rotate(90) scale(0.015 0.015)">
                            <path fill="white"
                              stroke="none"
                              strokeWidth="1"
                              strokeLinecap="round"
                              strokeLinejoin="miter"
                              opacity="1" d="M133.7,334.6c-14.5,0-26.2,11.7-26.2,26.2s11.7,26.2,26.2,26.2c14.5,0,26.2-11.7,26.2-26.2   S148.1,334.6,133.7,334.6z" />
                            <path fill="white"
                              stroke="none"
                              strokeWidth="1"
                              strokeLinecap="round"
                              strokeLinejoin="miter"
                              opacity="1" d="M378.3,334.6c-14.5,0-26.2,11.7-26.2,26.2s11.7,26.2,26.2,26.2c14.5,0,26.2-11.7,26.2-26.2   S392.8,334.6,378.3,334.6z" />
                            <path
                              d="M436.3,125H99.9c-23,0-42.6,16.6-46.5,39.2L29.2,305.7c-4.9,28.8,17.3,55.1,46.5,55.1h17.8   c0-22.2,18-40.2,40.2-40.2c22.2,0,40.2,18,40.2,40.2h164.3c0-22.2,18-40.2,40.2-40.2c22.2,0,40.2,18,40.2,40.2h17.8   c26.1,0,47.2-21.1,47.2-47.2V172.2C483.5,146.1,462.4,125,436.3,125z M380.7,178.1c0-7,5.6-12.6,12.6-12.6h29.2   c7,0,12.6,5.7,12.6,12.6v62.9c0,7-5.7,12.6-12.6,12.6h-29.2c-7,0-12.6-5.7-12.6-12.6V178.1z M294.5,178.1c0-7,5.6-12.6,12.6-12.6   h29.2c7,0,12.6,5.7,12.6,12.6v62.9c0,7-5.7,12.6-12.6,12.6h-29.2c-7,0-12.6-5.7-12.6-12.6V178.1z M208.4,178.1   c0-7,5.7-12.6,12.6-12.6h29.2c7,0,12.6,5.7,12.6,12.6v62.9c0,7-5.7,12.6-12.6,12.6H221c-7,0-12.6-5.7-12.6-12.6V178.1z    M155.9,277.7c-2.9,17.2-19.1,29.9-38.1,29.9H75.7c-2.6,0-4.2-1.2-5.2-2.2c-0.9-1-1.9-2.7-1.5-5l24.3-129.8c0.6-3,3.4-5.2,6.6-5.2   h75.2L155.9,277.7z M435.2,301.6H208.4c-3.9,0-7-3.1-7-7c0-3.9,3.1-7,7-7h226.8c3.9,0,7,3.1,7,7C442.2,298.4,439,301.6,435.2,301.6   z"
                              fill="white"
                              stroke="none"
                              strokeWidth="1"
                              strokeLinecap="round"
                              strokeLinejoin="miter"
                              opacity="1"
                            />
                          </g>
                          <polygon points="0 2.3, 1.8 3.5, 0 4.7" fill="white" />
                        </g>
                      </g>
                    )}
                    <polyline
                      points={ls.left_lane_boundary.map(pt => `${pt.x},${-pt.y}`).join(" ")}
                      className={`${classNameLeft} lane-boundary`}
                      fill="none"
                      strokeWidth={0.5}
                      vectorEffect="non-scaling-stroke"

                    />
                    <polyline
                      points={ls.right_lane_boundary.map(pt => `${pt.x},${-pt.y}`).join(" ")}
                      className={`${classNameRight} lane-boundary`}
                      fill="none"
                      strokeWidth={0.5}
                      vectorEffect="non-scaling-stroke"

                    />
                  </g>
                );
              })}
            </g>
            {lanes.map((ls, idx) => {
              return (
                <g key={idx}  >
                  {true && <polygon
                    points={[
                      ...ls.left_lane_boundary,
                      ...ls.right_lane_boundary.slice().reverse()
                    ].map(pt => `${pt.x},${-pt.y}`).join(" ")}
                    fill={
                      selectedTElement && ls.topoTL.includes(selectedTElement.id)
                        ? colors.trafficLight
                        : "none"
                    }
                    opacity="0.8"
                  />}
                </g>
              );
            })}
            {!anyConnected && pedcross.map((seg, idx) => {
              // Compute polygon points for the crossing
              const points = [
                ...seg.edge1,
                ...seg.edge2.slice().reverse(),
                seg.edge1[0],
              ];
              // Compute edge lengths to determine long side
              const len1 = Math.hypot(
                seg.edge1[0].x - seg.edge1[seg.edge1.length - 1].x,
                seg.edge1[0].y - seg.edge1[seg.edge1.length - 1].y
              );
              const len2 = Math.hypot(
                seg.edge2[0].x - seg.edge2[seg.edge2.length - 1].x,
                seg.edge2[0].y - seg.edge2[seg.edge2.length - 1].y
              );
              const longEdge = len1 > len2 ? seg.edge1 : seg.edge2;
              const otherEdge = len1 > len2 ? seg.edge2 : seg.edge1;
              // Stripes perpendicular to long side
              const dx = longEdge[longEdge.length - 1].x - longEdge[0].x;
              const dy = longEdge[longEdge.length - 1].y - longEdge[0].y;
              const length = Math.hypot(dx, dy) * 0.9;
              const ux = dx / length;
              const uy = dy / length;
              const px = -uy;
              const py = ux;
              const stripeSpacing = 1.5; // desired spacing between stripes
              const numStripes = Math.max(2, Math.floor(length / stripeSpacing));
              return (
                <g key={idx} >
                  <defs>
                    <clipPath id={`clip-cross-${idx}`}>
                      <polygon points={points.map(pt => `${pt.x},${-pt.y}`).join(" ")} />
                    </clipPath>
                  </defs>
                  <polygon
                    points={points.map(pt => `${pt.x},${-pt.y}`).join(" ")}
                    stroke={colors.crossing}
                    strokeWidth={0.5}
                    fill="none"
                    className="pedcross"
                  />
                  <g clipPath={`url(#clip-cross-${idx})`}>
                    {[...Array(numStripes + 1).keys()].map(i => {
                      const t = i / numStripes;
                      const bx = (longEdge[0].x + otherEdge[0].x) / 2 + t * dx;
                      const by = (longEdge[0].y + otherEdge[0].y) / 2 + t * dy;
                      const stripeLen = 1.5; // adjust as needed
                      return (
                        <line
                          key={i}
                          x1={bx - px * stripeLen}
                          y1={-(by - py * stripeLen)}
                          x2={bx + px * stripeLen}
                          y2={-(by + py * stripeLen)}
                          stroke="white"
                          strokeWidth={1}
                          opacity={0.85}
                        />
                      );
                    })}
                  </g>
                </g>
              );
            })}

            {/* Fixed origin marker */}

            <circle
              cx={pose.translation[0]}
              cy={-pose.translation[1]}
              r={1.0}

              fill={colors.ego}
            />
            <path
              d={`
    M ${pose.translation[0]} ${-pose.translation[1]}
    L ${pose.translation[0] + 10 * Math.cos(heading - 0.2)} ${-pose.translation[1] - 10 * Math.sin(heading - 0.2)}
    L ${pose.translation[0] + 10 * Math.cos(heading + 0.2)} ${-pose.translation[1] - 10 * Math.sin(heading + 0.2)}
    Z
  `}
              fill={colors.ego}
              fillOpacity={0.35}
              stroke={colors.ego}
              strokeWidth={0.4}
              strokeOpacity={0.9}
            />
          </g></g>
        <style>{`
        .lane-polygon:hover {
          stroke: ${colors.hover} !important;
          fill: ${colors.hover} !important;
        }
        .pedcross:hover {
          stroke: ${colors.hover} !important;
          fill: ${colors.hover} !important;
        }
        .lane-boundary:hover {
          stroke: ${colors.hover} !important;
          fill: none ;
        }
      `}</style>
      </svg></Box>
  );
}