/**
 * 🟠 connectContexts — dynamic, frame-based contextual relationships
 * ------------------------------------------------------------------
 * Handles temporal "is in" edges between nodes (e.g. vehicle → lane)
 * that vary across frames/timestamps.
 * ------------------------------------------------------------------
 */
export function connectContexts(newNode, nodes, visibleAt, intersectVisible) {
    const edges = [];
    const newUuid = String(newNode.data?.helpers?.uuid);
    const contextMap = newNode.data?.helpers?.context || {};
    

    // -------------- 1️⃣ Forward: newNode’s context references existing nodes --------------
    if (contextMap && Object.keys(contextMap).length > 0) {
        const uuidToFrames = {};
        Object.entries(contextMap).forEach(([frameKey, ctxUuid]) => {
            if (!ctxUuid) return;
            const uuid = String(ctxUuid);
            const frame = parseInt(frameKey, 10);
            if (!uuidToFrames[uuid]) uuidToFrames[uuid] = [];
            uuidToFrames[uuid].push(frame);
        });

        Object.entries(uuidToFrames).forEach(([uuid, frames]) => {
            const target = nodes.find((n) => String(n.data?.helpers?.uuid) === uuid);
            if (!target) return;
            
            edges.push({
                source: newNode.id,
                target: target.id,
                type: "dynamic",       // or dynamic
                category: "location", // location | occlusion | impact | regulation
                label: "is in",
                description: null,
                rule: null,
                targets: null,
                visibleAt: intersectVisible(visibleAt, frames)
            });
        });
    }

    // -------------- 2️⃣ Reverse: existing nodes reference this node --------------
    const reverseRefs = {};
    nodes.forEach((existing) => {
        const ctx = existing.data?.helpers?.context || {};
        Object.entries(ctx).forEach(([frameKey, ctxValue]) => {
            if (String(ctxValue) === newUuid) {
                if (!reverseRefs[existing.id]) reverseRefs[existing.id] = [];
                reverseRefs[existing.id].push(parseInt(frameKey, 10));
            }
        });
    });

    // Aggregate all reverse references into single edges
    Object.entries(reverseRefs).forEach(([sourceId, frames]) => {
        edges.push({
            source: sourceId,
            target: newNode.id,
            type: "dynamic",       // or dynamic
            category: "location", // location | occlusion | impact | regulation
            label: "is in",
            description: null,
            rule: null,
            targets: null,
            visibleAt: intersectVisible(visibleAt, frames)
        })
    });

    // -------------- 3️⃣ Retroactive resolution for delayed nodes --------------
    const unresolved = window.__unresolvedContexts || (window.__unresolvedContexts = {});
    if (contextMap && Object.keys(contextMap).length > 0) {
        Object.entries(contextMap).forEach(([frameKey, ctxUuid]) => {
            if (!ctxUuid) return;
            const uuid = String(ctxUuid);
            const frame = parseInt(frameKey, 10);
            if (!unresolved[uuid]) unresolved[uuid] = [];
            unresolved[uuid].push({ sourceId: newNode.id, frame });
        });
    }

    if (unresolved[newUuid]) {
        const grouped = {};
        unresolved[newUuid].forEach(({ sourceId, frame }) => {
            if (!grouped[sourceId]) grouped[sourceId] = [];
            grouped[sourceId].push(frame);
        });
        Object.entries(grouped).forEach(([sourceId, frames]) => {
            edges.push({
                source: sourceId,
                target: newNode.id,
                type: "dynamic",       // or dynamic
                category: "location", // location | occlusion | impact | regulation
                label: "is in",
                description: null,
                rule: null,
                targets: null,
                visibleAt: intersectVisible(visibleAt, frames)
            });
        });
        delete unresolved[newUuid];
    }

    // 🧹 Deduplicate edges by (source, target, label)
    const merged = {};
    for (const e of edges) {
        const key = `${e.source}-${e.target}-${e.label}`;
        if (!merged[key]) {
            merged[key] = { ...e };
        } else {
            // merge visibleAt frames if dynamic
            const prevFrames = merged[key].data?.visibleAt || [];
            const newFrames = e.data?.visibleAt || [];
            const combined = Array.from(new Set([...prevFrames, ...newFrames])).sort((a, b) => a - b);

            merged[key] = {
                ...merged[key],
                data: {
                    ...merged[key].data,
                    visibleAt: combined,
                    temporalLabels: Object.fromEntries(combined.map((f) => [f, e.label])),
                },
            };
        }
    }

    return Object.values(merged);

}