import React, { useCallback, useEffect, useRef, useState } from "react";
import ReactFlow, {
  Background,
  Controls,
  MiniMap,
  MarkerType,
  ReactFlowProvider,
  useReactFlow,
  useNodesInitialized,
  useStore,
} from "reactflow";
import { useLocation, useParams } from "react-router-dom";

import EdgeChip from "../../utils/EdgeChip.js";
import NodeChip from "../../utils/nodeChip.js";
import NodeTypePalette from "../../utils/NodePalette.js";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  ToggleButton,
  ToggleButtonGroup, Autocomplete
} from "@mui/material";
import "reactflow/dist/style.css";
import {
  Box,
  TextField,
  Button,
} from "@mui/material";
import { useGraph } from "../../components/GraphContext";
import { useTemplates } from "../../components/TemplateContext.js";


// Centres the graph once a newly loaded graph has been laid out and measured (the `fitView` prop only
// fits once, usually before the annotation has loaded), and again whenever the canvas changes size.
// It does not refit on frame changes, so playback and manual zoom/pan are not disturbed.
function AutoFit() {
  const rf = useReactFlow();
  const initialized = useNodesInitialized();
  const width = useStore((s) => s.width);
  const height = useStore((s) => s.height);
  const { logid } = useParams();
  const { search } = useLocation();
  const graphKey = `${logid}|${search}`;
  const pendingFit = useRef(true);
  const lastKey = useRef(graphKey);
  const wasInitialized = useRef(false);

  if (lastKey.current !== graphKey) {
    lastKey.current = graphKey;
    pendingFit.current = true;
  }

  useEffect(() => {
    const risingEdge = initialized && !wasInitialized.current;
    wasInitialized.current = initialized;
    if (!risingEdge || !pendingFit.current) return;
    pendingFit.current = false;
    const id = requestAnimationFrame(() => rf.fitView({ padding: 0.12 }));
    return () => cancelAnimationFrame(id);
  }, [initialized, graphKey, rf]);

  useEffect(() => {
    if (!initialized || !width || !height) return;
    const id = requestAnimationFrame(() => rf.fitView({ padding: 0.12 }));
    return () => cancelAnimationFrame(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [width, height]);

  return null;
}

// `compact`: used in the small graph pane of the combined view (no minimap).
export default function GraphTool({ compact = false }) {
  const {
    nodes,
    onNodesChange,
    edges,
    onEdgesChange,
    currentIndex,
    expandedNodeId,
    setExpandedNodeId,

    setSelectedEdgeId,
    selectedNode,
    setSelectedNode,
    setConnectedNodes,
    createEdge,
    selectedEdgeId
  } = useGraph();
  const {
    edgeLabelOptions, addEdgeTemplateLabel
  } = useTemplates();
  const [connectMode, setConnectMode] = useState(false);
  const [pendingConnection, setPendingConnection] = useState(null);
  const [edgeDialogOpen, setEdgeDialogOpen] = useState(false);
  const [paletteOpen, setPaletteOpen] = useState(false);
  const [palettePos, setPalettePos] = useState({ x: 0, y: 0 });


  const onPaneDoubleClick = useCallback((event) => {
    event.preventDefault();

    const bounds = event.currentTarget.getBoundingClientRect();

    // ✅ Compute position relative to the ReactFlow canvas
    const x = event.clientX - bounds.left;
    const y = event.clientY - bounds.top;

    setPalettePos({ x, y });
    setPaletteOpen(true);
  }, []);

  const nodeTypes = React.useMemo(() => ({
    chip: NodeChip
  }), []);
  const edgeTypes = React.useMemo(() => ({
    chip: EdgeChip
  }), []);



  const [edgeDialogData, setEdgeDialogData] = useState({
    source: null,
    target: null,
    type: "static", // static | dynamic
    category: "", // relative_position | impact | occlusion
    label: ""
  });

  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.shiftKey && e.altKey) {
        setConnectMode(true);
      }
    };
    const handleKeyUp = (e) => {
      if (!e.shiftKey || !e.altKey) {
        setConnectMode(false);
        setPendingConnection(null);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("keyup", handleKeyUp);
    };
  }, []);



  useEffect(() => {
    if (!selectedNode) return;
    function getConnectedNodes(selectedNode, nodes, edges) {
      if (!selectedNode || !edges?.length) return [];

      const connected = new Set();

      edges.forEach((edge) => {
        if (edge.source === selectedNode.id) {
          connected.add(edge.target);
        } else if (edge.target === selectedNode.id) {
          connected.add(edge.source);
        }
      });

      return Array.from(connected);
    }
    setConnectedNodes(getConnectedNodes(selectedNode, nodes, edges))
  }, [nodes, edges, selectedNode, setConnectedNodes]);

  useEffect(() => {
    const isNodeVisibleAt = (node, index) => {
      if (!node) return false;
      if (node.data?.type === "ego" || node.id === "Ego") return true;
      const vis = Object.keys(node.data.visibleAt).map(Number) || [];
      return vis.includes(index);
    };

    if (!selectedNode) return;
    // If the selected node no longer exists at this frame, deselect it
    if (!isNodeVisibleAt(selectedNode, currentIndex)) {
      setSelectedNode(null);
    }
  }, [selectedNode, currentIndex, setSelectedNode]);





  const onDragOver = (event) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
  };



  const onConnect = useCallback(
    (params) => {
      // open dialog for structured input
      setEdgeDialogData({
        source: params.source,
        target: params.target,
        type: "static",
        category: "",
        label: "",
      });
      setEdgeDialogOpen(true);
    },
    []
  );


  const handleCreateEdge = async () => {
    const {
      source,
      target,
      type,
      category,
      label
    } = edgeDialogData;
    const visibleAt = [currentIndex]
    createEdge({
      source,
      target,
      type,
      category,
      label, 
      visibleAt
    });
    if (!edgeLabelOptions[category]?.includes(label)) {
      await addEdgeTemplateLabel(edgeDialogData.category, label);
    }

    setEdgeDialogOpen(false);
  };


  const onNodeClick = useCallback(
    (_, node) => {

      if (connectMode) {
        // if we're in connect mode
        if (!pendingConnection) {
          // first node clicked
          setPendingConnection(node);
        } else if (pendingConnection.id !== node.id) {
          // second node clicked → connect them
          const params = {
            source: pendingConnection.id,
            target: node.id,
          };
          onConnect(params); // reuse your existing logic
          setPendingConnection(null);
        }
        return; // don’t open the panel when connecting
      }

      // Normal behavior (open side panel)
      setSelectedNode(node);
      setSelectedEdgeId(null);

    },
    [connectMode, pendingConnection, onConnect, setSelectedNode, setSelectedEdgeId]
  );




  const onPaneClick = useCallback(() => {
    setSelectedNode(null);
    setSelectedEdgeId(null);
    setExpandedNodeId(null);

  }, [setExpandedNodeId, setSelectedNode, setSelectedEdgeId]);




  const visibleNodes = nodes.filter((n) => {
    if (n.type === "group") return true;           // ✅ always show group nodes
    if (n.data?.type === "ego" || n.id === "Ego") return true;
    const vis = Object.keys(n.data?.visibleAt).map(Number) || [];
    return vis.includes(currentIndex);
  }).map((n) => (
    // Lift the expanded node above edges and edge labels (they render in separate layers).
    n.data?.helpers?.uuid === expandedNodeId ? { ...n, zIndex: 2000 } : n
  ));
  const visibleNodeIds = new Set(visibleNodes.map((n) => n.id));
  const visibleEdges = edges
    .filter((e) => {
      const temporal = e.data?.temporalLabels;
      let edgeVisible = false;

      if (typeof temporal === "string") {
        edgeVisible = true;
      } else if (temporal && typeof temporal === "object") {
        edgeVisible = Object.keys(temporal).map(Number).includes(currentIndex);
      } else {
        edgeVisible = false;
      }

      const sourceVisible = visibleNodeIds.has(e.source);
      const targetVisible = visibleNodeIds.has(e.target);

      if (!sourceVisible || !targetVisible || !edgeVisible) return false;

      const labels = e.data?.temporalLabels || {};
      const allTimes = Object.keys(labels)
        .map((t) => parseInt(t))
        .sort((a, b) => a - b);

      if (allTimes.length === 0) return false;

      const firstLabelTime = allTimes[0];
      return currentIndex >= firstLabelTime;
    })
    .map((e) => {
      const labels = e.data?.temporalLabels || {};
      const allTimes = Object.keys(labels)
        .map((t) => parseInt(t))
        .sort((a, b) => a - b);

      const activeTime = [...allTimes].reverse().find((t) => t <= currentIndex);

      const sourceNode = nodes.find((n) => n.id === e.source);
      const targetNode = nodes.find((n) => n.id === e.target);

      const srcUuid = sourceNode?.data?.helpers?.uuid;
      const tgtUuid = targetNode?.data?.helpers?.uuid;

      const isConnectedToSelected =
        selectedNode &&
        (srcUuid === selectedNode.data?.helpers?.uuid ||
          tgtUuid === selectedNode.data?.helpers?.uuid);

      const isConnectedToExpanded =
        expandedNodeId &&
        (srcUuid === expandedNodeId || tgtUuid === expandedNodeId);

      const showLabels = isConnectedToSelected || isConnectedToExpanded;

      // 🎨 Determine label text
      let activeLabel = "";
      if (showLabels) {
        if (e.data?.category === "dynamic") {
          activeLabel = activeTime !== undefined ? labels[activeTime] : "";
        } else if (e.data?.category === "static") {
          activeLabel = labels;
        }
      }

      // 🎨 Determine edge style
      let style = { ...e.style };
      if (showLabels) {
        style = { ...style, opacity: 1 };
      } else {
        // dim unconnected edges when something is selected or expanded
        if (selectedNode || expandedNodeId) {
          style = { ...style, stroke: "#888", opacity: 0.4 };
        } else {
          style = { ...style, opacity: 1 }; // normal if nothing selected
        }
      }

      return { ...e, label: activeLabel, style };
    }).filter(Boolean); // remove any null edges


  // highlight only edges connected to the selected node
  const edgesWithAnimation = visibleEdges.map((e) => {
    const isConnected =
      e.id === selectedEdgeId;
    return {
      ...e,
      animated: !!isConnected,
      style: {
        ...e.style,
        opacity: isConnected ? 1 : 0.3,
      },
    };
  });




  return (
    <ReactFlowProvider>
      <Box
        sx={{
          height: "100%",
          width: "100%",
          display: "flex",
          background: "#101020",

          color: "#fff",
        }}
      >

        {/* Edge creation dialog */}
        {edgeDialogOpen && (
          <Box>
            <Dialog
              open={edgeDialogOpen}
              onClose={() => setEdgeDialogOpen(false)}
              maxWidth="xs"
              fullWidth
            >
              <DialogTitle>Create Edge</DialogTitle>
              <DialogContent sx={{ display: "flex", flexDirection: "column", gap: 2, mt: 1 }}>
                {/* 🟠 Static / Dynamic toggle */}
                <ToggleButtonGroup
                  value={edgeDialogData.type || "static"}
                  exclusive
                  fullWidth
                  onChange={(e, newType) => {
                    if (newType !== null) {
                      setEdgeDialogData((prev) => ({ ...prev, type: newType }));
                    }
                  }}
                  sx={{
                    display: "flex",
                    justifyContent: "space-between",
                    mb: 2,
                  }}
                >
                  <ToggleButton
                    value="static"
                    sx={{
                      flex: 1,
                      textTransform: "capitalize",
                      borderRadius: "8px 0 0 8px",
                    }}
                  >
                    Static
                  </ToggleButton>
                  <ToggleButton
                    value="dynamic"
                    sx={{
                      flex: 1,
                      textTransform: "capitalize",
                      borderRadius: "0 8px 8px 0",
                    }}
                  >
                    Dynamic
                  </ToggleButton>
                </ToggleButtonGroup>
                <ToggleButtonGroup
                  value={edgeDialogData.category}
                  exclusive
                  fullWidth
                  onChange={(e, newCategory) => {
                    if (newCategory !== null) {
                      setEdgeDialogData((prev) => ({
                        ...prev,
                        category: newCategory
                      }));
                    }
                  }}
                  sx={{
                    display: "flex",
                    justifyContent: "space-between",
                    mb: 2,
                  }}
                >
                  <ToggleButton value="location" sx={{ flex: 1, textTransform: "capitalize" }}>
                    {"<Location>"}
                  </ToggleButton>
                  <ToggleButton value="impact" sx={{ flex: 1, textTransform: "capitalize" }}>
                    impacts
                  </ToggleButton>
                  <ToggleButton value="regulation" sx={{ flex: 1, textTransform: "capitalize" }}>
                    regulates
                  </ToggleButton>
                  <ToggleButton value="other" sx={{ flex: 1, textTransform: "capitalize" }}>
                    other
                  </ToggleButton>

                </ToggleButtonGroup>

                {true && (
                  <Autocomplete
                    freeSolo
                    disableClearable
                    options={edgeLabelOptions[edgeDialogData.category] || []}
                    inputValue={edgeDialogData.label}
                    onInputChange={(e, v) =>
                      setEdgeDialogData(prev => ({ ...prev, label: v }))
                    }
                    renderInput={(params) => (
                      <TextField
                        {...params}
                        label="Relation"
                        placeholder="e.g. is left of"

                      />
                    )}
                  />
                )}


              </DialogContent>
              <DialogActions>
                <Button onClick={() => setEdgeDialogOpen(false)}>Cancel</Button>
                <Button variant="contained" onClick={handleCreateEdge}>
                  Create
                </Button>
              </DialogActions>
            </Dialog>
          </Box>
        )}







        {/* Canvas */}
        <Box sx={{ flexGrow: 1, }}>
          {/* 🌟 Floating Export/Import Buttons */}





          <ReactFlow
            nodeTypes={nodeTypes}
            edgeTypes={edgeTypes}
            nodeDragHandle=".chip-drag"
            onPaneContextMenu={onPaneDoubleClick}
            nodes={visibleNodes}
            edges={edgesWithAnimation}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            onConnect={onConnect}
            onDragOver={onDragOver}
            onNodeClick={onNodeClick}
            onPaneClick={onPaneClick}
            selectionKeyCode="Control"           // (or 'Meta' on Mac)
            multiSelectionKeyCode="Shift"        // Hold Shift to select multiple
            defaultEdgeOptions={{
              markerEnd: { type: MarkerType.ArrowClosed, minWidth: 2, height: 2 },
              labelBgStyle: {
                fill: "rgba(255,255,255,0.9)",
                color: "#000",
                padding: 0,
                borderRadius: 4,
              },
              labelStyle: { fill: "#000", fontWeight: 400, fontSize: "6px" },
            }}
            fitView
            connectable
            defaultViewport={{ x: 0, y: 0, zoom: 0.3 }}  // 👈 smaller zoom (60%)
          >
            {!compact && <MiniMap />}
            <Controls />
            <Background

              gap={20}          // optional: spacing between lines
              size={0.8}          // optional: line thickness
              variant="dots"    // or "lines"
              style={{ backgroundColor: "background.paper" }} // overall canvas background
            />


            <NodeTypePalette open={paletteOpen} top={palettePos.y} left={palettePos.x} setPaletteOpen={setPaletteOpen}></NodeTypePalette>
            <AutoFit />
          </ReactFlow>
        </Box>

      </Box>
    </ReactFlowProvider>
  );
}