// src/components/GraphContext.js
import React, { createContext, useContext, useRef, useState } from "react";
import { useNodesState, useEdgesState } from "reactflow";
import { createNode, rebuildAllEdges } from "../utils/createNode"; // we’ll define below
import { useTemplates } from "../components/TemplateContext";

const GraphContext = createContext();

export const GraphProvider = ({ children }) => {
  const { templatesRef } = useTemplates();
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [expandedNodeId, setExpandedNodeId] = useState(null);
  const [selectedNode, setSelectedNode] = useState(null);
  const [selectedEdgeId, setSelectedEdgeId] = useState(null);
  const [expandedEdgeId, setExpandedEdgeId] = useState(null);
  const [connectedNodes, setConnectedNodes] = useState(null);
  const [pendingEdges, setPendingEdges] = useState([]);
  const [contextMenu, setContextMenu] = useState(null);
  const globalCounter = useRef({});


  const addNode = (type, position, properties = {}, helpers = {}, visibleAt = null) => {
    const { node: newNode, edges: newEdges } = createNode({
      type: type,
      position,
      properties,
      helpers,
      templatesRef,
      counterRef: globalCounter,
      currentIndex,
      visibleAt,
      nodes,
      setPendingEdges
    });

    setNodes((prev) => [...prev, newNode]);
    setSelectedNode(null);
    if (newEdges.length > 0) {
      newEdges.forEach(edge => {
        createEdge(edge);

      });

    }
  };
  const addNewEdges = () => {
     setEdges((prevEdges) =>
    prevEdges.filter((edge) => {
      const sourceNode = nodes.find((n) => n.id === edge.source);
      const targetNode = nodes.find((n) => n.id === edge.target);

      const isLaneToLane =
        sourceNode?.data?.type === "lane" &&
        targetNode?.data?.type === "lane";

      const isLeftRightRelation =
        edge?.data?.temporalLabels === "is left of" ||
        edge?.data?.temporalLabels === "is right of" ||
        edge?.label === "is left of" ||
        edge?.label === "is right of";

      return !(isLaneToLane && isLeftRightRelation);
    })
  );

    const { deduped: deduped } = rebuildAllEdges({
      nodes,
      setPendingEdges
    });

   if (deduped.length > 0) {
      deduped.forEach(edge => {
        createEdge(edge);
      });

    }
  };

  function deepClone(obj) {
    if (obj === null || typeof obj !== "object") return obj;
    if (Array.isArray(obj)) return obj.map(deepClone);

    const out = {};
    for (const key in obj) {
      out[key] = deepClone(obj[key]);
    }
    return out;
  }

  function updateNode(uuid, updater) {
    setNodes(ns =>
      ns.map(n => {
        if (n.data?.helpers?.uuid !== uuid) return n;

        // ❗ deep clone node.data so nested temporal maps don’t collapse
        const clonedData = deepClone(n.data);

        const updatedData = updater(clonedData);

        return {
          ...n,
          data: updatedData,
        };
      })
    );
  }

  function updateVisibility(uuid, next) {
    updateNode(uuid, data => {
      const oldMap = data.visibleAt || {};
      const updatedMap = { ...oldMap, [currentIndex]: next };
      return { ...data, visibleAt: updatedMap };
    });
  }

  function deleteProperty(uuid, key, temporal = false) {
    updateNode(uuid, (data) => {
      const props = { ...(data.properties || {}) };
      const { [key]: _removed, ...rest } = props;

      return { ...data, properties: rest };
    });
  }

  function updateProperty(uuid, key, value) {
    updateNode(uuid, (data) => {
      const props = { ...(data.properties || {}) };

      // 1) template type: stored as data.type (NOT in helpers)
      const templateType = data.type;
      const template = templatesRef.current?.[templateType];

      // 2) metadata for this property
      const meta = template?.defaultProperties?.find((p) => p.key === key);

      const isLocked = meta?.locked === true; // non-temporal = static
      const isTemporal = !isLocked;           // default → temporal

      if (isTemporal) {
        const old = props[key] || {};
        props[key] = { ...old, [currentIndex]: value };
      } else {
        props[key] = value;
      }

      return { ...data, properties: props };
    });
  }

  function deletePositionThisFrame(uuid, camera) {
    let delete_from_frame = false;
    updateNode(uuid, (data) => {
      const helpers = { ...(data.helpers || {}) };
      const CP = { ...(helpers.ClickPosition || {}) };

      const frameCP = CP[currentIndex];
      if (!frameCP || !frameCP[camera]) return data;

      // Remove only this camera
      const updatedFrameCP = { ...frameCP };
      delete updatedFrameCP[camera];

      // If frame has no cameras left → remove frame entry
      if (Object.keys(updatedFrameCP).length === 0) {
        delete_from_frame = true;
      } else {
        CP[currentIndex] = updatedFrameCP;
      }

      helpers.ClickPosition = CP;

      return {
        ...data,
        helpers,
      };
    });
    if (delete_from_frame) {
      deleteNodeThisFrame(uuid)
    }
  }

  function updateHelpers(uuid, key, value, index = currentIndex) {
    updateNode(uuid, (data) => {
      const helpers = { ...(data.helpers || {}) };

      const current = helpers[key];

      if (current && typeof current === "object" && !Array.isArray(current)) {
        helpers[key] = {
          ...current,
          [index]: value,
        };
      } else {
        helpers[key] = value;
      }

      return { ...data, helpers };
    });
  }

  function isTemporalField(value) {
    return value && typeof value === "object" && !Array.isArray(value);
  }

  const propagateForward = (nodeId, nodeLabel) => {
    const nextFrame = currentIndex + 1;

    setNodes((nds) =>
      nds.map((n) => {
        if (n.id !== nodeId) return n;

        const data = { ...n.data };

        // 1) visibleAt
        data.visibleAt = { ...data.visibleAt, [nextFrame]: true };

        // 2) ClickPosition
        const CP = data.helpers?.ClickPosition || {};
        const currCP = CP[currentIndex];
        const newCP = { ...CP };
        newCP[nextFrame] = currCP ? structuredClone(currCP) : {};
        data.helpers = { ...data.helpers, ClickPosition: newCP };

        // 3) temporal node.properties
        const props = data.properties || {};
        const newProps = { ...props };

        for (const key of Object.keys(props)) {
          if (isTemporalField(props[key])) {
            const propObj = { ...props[key] };
            propObj[nextFrame] = propObj[currentIndex];
            newProps[key] = propObj;
          }
        }

        data.properties = newProps;

        return { ...n, data };
      })
    );

    // 4) temporal edges: copy label
    setEdges((eds) =>
      eds.map((e) => {
        if (e.source !== nodeLabel && e.target !== nodeLabel) return e;

        if (typeof e.data.temporalLabels === "object") {
          const t = { ...e.data.temporalLabels };
          t[nextFrame] = t[currentIndex];
          return { ...e, data: { ...e.data, temporalLabels: t } };
        }
        return e;
      })
    );

    setCurrentIndex(nextFrame);
  };

  const propagateBackward = (nodeId, nodeLabel) => {
    const prevFrame = currentIndex - 1;
    if (prevFrame < 0) { return }

    setNodes((nds) =>
      nds.map((n) => {
        if (n.id !== nodeId) return n;

        const data = { ...n.data };

        // 1) visibleAt
        data.visibleAt = { ...data.visibleAt, [prevFrame]: true };

        // 2) ClickPosition
        const CP = data.helpers?.ClickPosition || {};
        const currCP = CP[currentIndex];
        const newCP = { ...CP };
        newCP[prevFrame] = currCP ? structuredClone(currCP) : {};
        data.helpers = { ...data.helpers, ClickPosition: newCP };

        // 3) temporal node.properties
        const props = data.properties || {};
        const newProps = { ...props };

        for (const key of Object.keys(props)) {
          if (isTemporalField(props[key])) {
            const propObj = { ...props[key] };
            propObj[prevFrame] = propObj[currentIndex];
            newProps[key] = propObj;
          }
        }

        data.properties = newProps;

        return { ...n, data };
      })
    );

    // 4) temporal edges: copy label
    setEdges((eds) =>
      eds.map((e) => {
        if (e.source !== nodeLabel && e.target !== nodeLabel) return e;

        if (typeof e.data.temporalLabels === "object") {
          const t = { ...e.data.temporalLabels };
          t[prevFrame] = t[currentIndex];
          return { ...e, data: { ...e.data, temporalLabels: t } };
        }
        return e;
      })
    );

    setCurrentIndex(prevFrame);
  };

  function deleteNodeThisFrame(nodeId) {
    setNodes((nds) =>
      nds.map((n) => {
        if (n.data.helpers.uuid !== nodeId) return n;

        const data = { ...n.data };

        // 1) remove visibility
        const vis = { ...data.visibleAt };
        delete vis[currentIndex];
        data.visibleAt = vis;

        // 2) remove ClickPosition
        const CP = { ...(data.helpers?.ClickPosition || {}) };
        delete CP[currentIndex];
        data.helpers = { ...data.helpers, ClickPosition: CP };

        // 3) remove temporal property entries
        const props = { ...data.properties };
        for (const key of Object.keys(props)) {
          if (isTemporalField(props[key])) {
            const p = { ...props[key] };
            delete p[currentIndex];
            props[key] = p;
          }
        }

        data.properties = props;

        return { ...n, data };
      })
    );

    // 4) edge temporalLabels

    const nodeLabel = nodes.find(n => n.data.helpers.uuid === nodeId).id

    edges.map((e) => {
      if (e.source !== nodeLabel && e.target !== nodeLabel) return e;
      else { deleteEdgeThisFrame(e.id) }
      return e;
    })

  }

  const cloneValue = (v) => {
    if (v && typeof v === "object") return structuredClone(v); // deep copy
    return v; // primitives are safe
  };

  function propagatePropertyBackward(uuid, propertyKey) {
    updateNode(uuid, (data) => {
      const props = { ...(data.properties || {}) };
      const visibleAt = { ...(data.visibleAt || {}) };
      const prop = props[propertyKey];

      // Must be temporal
      if (!isTemporalField(prop)) {

        return data
      };

      const currentValue = prop[currentIndex];
      if (currentValue === undefined) return data;

      const updatedProp = { ...prop };

      const minFrame = Math.min(
        currentIndex,
        ...Object.keys(visibleAt).map(Number)
      );
      // Fill backwards to frame 0
      for (let i = currentIndex - 1; i >= minFrame; i--) {
        updatedProp[i] = cloneValue(currentValue); 
      }

      props[propertyKey] = updatedProp;

      return {
        ...data,
        properties: props,
      };
    });
  }

  function propagatePropertyForward(uuid, propertyKey) {
    updateNode(uuid, (data) => {
      
      const props = { ...(data.properties || {}) };
      const visibleAt = { ...(data.visibleAt || {}) };
      const prop = props[propertyKey];

      // Must be a temporal property
      if (!isTemporalField(prop)) return data;

      const currentValue = prop[currentIndex];
      if (currentValue === undefined) return data;

      const updatedProp = { ...prop };

      // Determine how far we propagate
      // Option A: up to max existing frame
      const maxFrame = Math.max(
        currentIndex,
        ...Object.keys(visibleAt).map(Number)
      );
     

      for (let i = currentIndex + 1; i <= maxFrame; i++) {
        updatedProp[i] = currentValue;
      }
    
      props[propertyKey] = updatedProp;

      return {
        ...data,
        properties: props,
      };
    });
  }

  const deleteNodeEverywhere = (uuid) => {
    const label = nodes.find(n => n.data.helpers.uuid === uuid).id

    setNodes((nds) => nds.filter((n) => n.data.helpers.uuid !== uuid));

    setEdges((eds) =>
      eds.filter((e) => {

        return e.source !== label && e.target !== label
      })
    );
  };
  const deleteEdge = (id) => {
    setEdges((eds) => eds.filter((e) => e.id !== id));
  };

  function deleteEdgeThisFrame(edgeId) {
    setEdges((eds) =>
      eds.flatMap((e) => {

        if (e.id !== edgeId) return [e];


        const data = { ...e.data };
        const labels = data.temporalLabels;

        // Static edges cannot be deleted per-frame
        if (typeof labels !== "object") {
          console.warn("Attempted deleteEdgeThisFrame on static edge:", e.id);
          return [e]; // keep as is
        }

        // Clone and remove THIS frame
        const newLabels = { ...labels };
        delete newLabels[currentIndex];

        // If no frames left → delete edge entirely
        if (Object.keys(newLabels).length === 0) {
          return []; // remove edge
        }
        // Otherwise keep edge but update labels
        return [
          {
            ...e,
            data: {
              ...data,
              temporalLabels: newLabels,
            },
          },
        ];
      })
    );
  }

  function createEdge({
    source,
    target,
    type,          // "static" | "dynamic"
    category,      // "location" | "occlusion" | "impact" | "regulation"
    label,         // string
    visibleAt
  }) {
    const isDynamic = type === "dynamic";

    let temporalLabels;

    if (isDynamic) {
      const visibleAtArr = Array.isArray(visibleAt)
        ? visibleAt
        : visibleAt
          ? Object.keys(visibleAt).map(Number)
          : [];

      temporalLabels = {};
      for (const frame of visibleAtArr) {
        temporalLabels[frame] = label;
      }



    } else {
      temporalLabels = label; // static
    }


    const newEdge = {
      id: `${source}-${target}-${Date.now()}`,
      type: "chip",
      source,
      target,
      //label: isDynamic ? temporalLabels[currentIndex] : label,
      data: {
        category,
        temporalLabels
      },
    };

    // Save edge
    setEdges((eds) => [...eds, newEdge]);

    return newEdge;
  }

  function updateEdge(edgeId, key, value) {
    setEdges((eds) =>
      eds.map((e) => {
        if (e.id !== edgeId) return e;
        // Deep clone to preserve temporal maps
        let cloned = deepClone(e);

        const isDynamic = typeof cloned.data?.temporalLabels === "object";
        const path = key.split(".");


        if (path[0] === "temporalLabels") {
          if (isDynamic) {
            // Update temporal label
            const t = cloned.data.temporalLabels;
            cloned.data.temporalLabels = {
              ...t,
              [currentIndex]: value,
            };
          } else {
            // Static
            cloned.data.temporalLabels = value; // consistent static format
          }
          return cloned;
        }

        if (path[0] === "extra") {
          if (!cloned.data.extra) { return null };

          // traverse nested
          let obj = cloned.data.extra;
          obj[path[1]] = value;

          return cloned;
        }

        // cloned.data[key] = value;


        return cloned;
      })
    );
  }

  function propagateEdgeBackward(edgeId) {
    const nextFrame = currentIndex - 1;

    if (nextFrame >= 0) {
      setEdges((eds) =>
        eds.map((e) => {
          if (e.id !== edgeId) return e;

          // Only temporal edges propagate
          if (typeof e.data.temporalLabels === "object") {
            const t = { ...e.data.temporalLabels };
            t[nextFrame] = t[currentIndex];
            return { ...e, data: { ...e.data, temporalLabels: t } };
          }

          return e;
        })
      );

      setCurrentIndex(nextFrame);
    }
    else { return }
  }
  function propagateEdgeForward(edgeId) {
    const nextFrame = currentIndex + 1;

    setEdges((eds) =>
      eds.map((e) => {
        if (e.id !== edgeId) return e;

        // Only temporal edges propagate
        if (typeof e.data.temporalLabels === "object") {
          const t = { ...e.data.temporalLabels };
          t[nextFrame] = t[currentIndex];
          return { ...e, data: { ...e.data, temporalLabels: t } };
        }

        return e;
      })
    );

    setCurrentIndex(nextFrame);
  }



  return (
    <GraphContext.Provider
      value={{
        nodes,
        setNodes,
        onNodesChange,
        edges,
        setEdges,
        onEdgesChange,
        addNode,
        addNewEdges,
        currentIndex,
        counterRef: globalCounter,
        setCurrentIndex,
        expandedNodeId,
        setExpandedNodeId,
        selectedNode,
        setSelectedNode,
        selectedEdgeId,
        setSelectedEdgeId,
        expandedEdgeId,
        setExpandedEdgeId,
        connectedNodes,
        setConnectedNodes,
        pendingEdges,
        setPendingEdges,
        contextMenu,
        setContextMenu,
        deleteNodeThisFrame,
        deleteNodeEverywhere,
        propagateBackward,
        propagateForward,
        propagatePropertyForward,
        propagatePropertyBackward,
        deletePositionThisFrame,


        //general node management
        updateVisibility,
        updateProperty,
        deleteProperty,
        updateHelpers,
        createEdge,
        updateEdge,
        deleteEdge,
        deleteEdgeThisFrame,
        propagateEdgeForward,
        propagateEdgeBackward
      }}
    >

      {children}
    </GraphContext.Provider>
  );
};

export const useGraph = () => useContext(GraphContext);