// Drafts kept in the browser's localStorage, one per log and start mode
// ("annotated" = edits on the released graph, "empty" = graph built from scratch),
// so work survives a reload and switching modes never overwrites the other mode.
// Storage can be unavailable (private mode, blocked site data); every access is guarded.
const PREFIX = "mapvqa-annotator:draft:";
export const MODES = ["annotated", "empty"];

const key = (logid, mode) => `${PREFIX}${logid}:${mode}`;

export function readDraft(logid, mode) {
  try {
    const raw = window.localStorage.getItem(key(logid, mode));
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

export function writeDraft(logid, mode, annotation) {
  try {
    window.localStorage.setItem(
      key(logid, mode),
      JSON.stringify({ ...annotation, savedAt: new Date().toISOString() })
    );
  } catch {
    // storage full or unavailable: the user can still download the file
  }
}

export function deleteDraft(logid, mode) {
  try {
    window.localStorage.removeItem(key(logid, mode));
  } catch {
    // ignore
  }
}

export function hasAnyDraft(logid) {
  return MODES.some((m) => readDraft(logid, m) !== null);
}
