import React from "react";
import { Box } from "@mui/material";
import { useGraph } from "../components/GraphContext";


// Shared look of the node labels drawn on the camera images: a compact pill chip.
const chipSx = (color, active) => ({
  display: "inline-flex",
  alignItems: "center",
  gap: "3px",
  height: 18,
  maxWidth: "100%",
  boxSizing: "border-box",
  pl: "7px",
  pr: "4px",
  borderRadius: "999px",
  opacity: active ? 1 : 0,
  backgroundColor: active ? color : "grey",
  border: "1px solid rgba(0,0,0,0.28)",
  boxShadow: "0 1px 3px rgba(0,0,0,0.45)",
  color: "#111",
  fontFamily: '"Figtree", system-ui, sans-serif',
  fontSize: "10.5px",
  fontWeight: 600,
  lineHeight: 1,
  whiteSpace: "nowrap",
  cursor: "pointer",
  userSelect: "none",
  transition: "opacity 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease",
  "&:hover": { filter: "brightness(1.08)", boxShadow: `0 0 0 2px rgba(255,255,255,0.85), 0 1px 3px rgba(0,0,0,0.45)` },
});

const chipTextSx = { overflow: "hidden", textOverflow: "ellipsis", minWidth: 0 };

const starStyle = {
  flexShrink: 0,
  display: "inline-flex",
  alignItems: "center",
  justifyContent: "center",
  width: 13,
  height: 13,
  borderRadius: "50%",
  fontSize: "10px",
  lineHeight: 1,
  color: "#111",
  background: "rgba(255,255,255,0.45)",
  cursor: "pointer",
  userSelect: "none",
};

const SvgPointLabelImpl = ({
  id,
  nodeId,
  x,
  y,
  setGraphView,
  setListView,
  camera,
  color = "#ccc",
  label,
  textWidth = 60,
  radius = 4,
  bbox = null
}) => {
  const bubbleY = y - 24;
  // Room for the label text, padding and the star, centred on the point.
  const chipWidth = Math.max(textWidth, String(label ?? "").length * 6.4 + 32);
  const lineTopY = y - 18;
  const { expandedNodeId, edges, currentIndex, setExpandedNodeId, selectedNode, setSelectedNode, expandedEdgeId, setExpandedEdgeId, nodes, setContextMenu } =
    useGraph();

  // whether this label is the selected one
  const isSelected =
    selectedNode === null && expandedEdgeId === null ? true :
      expandedEdgeId === null ?
        selectedNode?.data.helpers.uuid === nodeId :
        edges.find(e => e.source === id && expandedEdgeId === e.id) || edges.find(e => e.target === id && expandedEdgeId === e.id) ? true : false;
  const isExpanded = expandedNodeId === nodeId;

   const matchedNode = nodes.find(n => n.data?.helpers?.uuid === nodeId);
  const nodeUniqueKey = matchedNode?.data?.helpers?.uniqueKey || {};
 
  const uniqueKeysForThisFrame = nodeUniqueKey[currentIndex] || [];
  const hasUniqueKey = uniqueKeysForThisFrame.length !== 0;

  const uniqueKeyTooltip = uniqueKeysForThisFrame;

  const handleClick = (e) => {
    e.stopPropagation();

    // find the node whose helpers.uuid equals nodeId
    const matchedNode = nodes.find(
      (n) => n.data?.helpers?.uuid === nodeId
    );

    if (matchedNode) {
      setSelectedNode(matchedNode);
      setExpandedEdgeId(null)
    } else {
      console.warn("No node found for uuid:", nodeId);
    }
  };

  const handleDoubleClick = (e) => {
    e.stopPropagation();

    setExpandedNodeId(nodeId);
    setExpandedEdgeId(null)

    if (e.shiftKey) {
      // SHIFT + double-click → open Graph View
      setGraphView(true);
      setListView(false);
    } else {
      // Double-click → open List View (default)
      setListView(true);
      setGraphView(false);
    }
  };

  return (
    <g key={id} filter={isExpanded ? "url(#nodeGlow)" : "none"}>
      {/* Point */}
      <circle
        cx={x}
        cy={y}
        r={radius}
        fill={isSelected || isExpanded ? color : "grey"}
        opacity={isSelected || isExpanded ? 1 : 0}
        stroke={isSelected || isExpanded ? "white" : "transparent"}
        strokeWidth={1.5}
      />

      {/* Connector line */}
      <line
        x1={x}
        y1={y}
        x2={x}
        y2={lineTopY}
        opacity={isSelected || isExpanded ? 1 : 0}
        stroke={isSelected || isExpanded ? "white" : "lightgrey"}
        strokeWidth={1}
        strokeDasharray="2,2"
      />

      {/* Label bubble */}
      <foreignObject
        x={x - chipWidth / 2}
        y={bubbleY}
        width={chipWidth}
        height={24}
        style={{ pointerEvents: "none", overflow: "visible" }}
        onClick={handleClick}
        onDoubleClick={handleDoubleClick}
        onContextMenu={(e) => {
          e.preventDefault();
          e.stopPropagation();

          setContextMenu({
            x: e.clientX,
            y: e.clientY,
            nodeId,
            camera,
            mode: "cameraAssign",  // 🔥 NEW, 
            bbox: (bbox != null) ? bbox : "none"
          });
        }}
      >
        <Box sx={{ display: "flex", justifyContent: "center", alignItems: "flex-end", height: "100%", pb: "3px", boxSizing: "border-box" }}>
          <Box sx={{ ...chipSx(color, isSelected || isExpanded), pointerEvents: "auto" }}>
            <Box component="span" sx={chipTextSx}>{label}</Box>
            <span
              title={uniqueKeyTooltip}
              onClick={(e) => {
                e.stopPropagation();
                e.preventDefault();
                setContextMenu({
                  x: e.clientX,
                  y: e.clientY,
                  mode: "uniqueKeySelect",
                  nodeId
                });
              }}
              style={starStyle}
            >
              {hasUniqueKey ? "★" : "☆"}
            </span>
          </Box>
        </Box>
      </foreignObject>
    </g>
  );
};

const NodeLabelImpl = ({
  id,
  nodeId,
  label,
  setGraphView,
  setListView,
  camera,
  color = "#ccc",
  anchorX,
  anchorY,
  offsetY = -22,
  minWidth = 40,
  zIndex = 9999,
}) => {

  const {
    expandedNodeId,
    setExpandedNodeId,
    expandedEdgeId,
    selectedNode,
    setSelectedNode,
    setExpandedEdgeId,
    nodes,
    edges,
    setContextMenu, 
    currentIndex
  } = useGraph();

  // ⚙️ same logic as SvgPointLabel
  const isSelected =
    selectedNode === null && expandedEdgeId === null ? true :
      expandedEdgeId === null ?
        selectedNode?.data.helpers.uuid === nodeId :
        edges.find(e => e.source === label && expandedEdgeId === e.id) || edges.find(e => e.target === label && expandedEdgeId === e.id) ? true : false;
  const isExpanded = expandedNodeId === nodeId;
  const matchedNode = nodes.find(n => n.data?.helpers?.uuid === nodeId);
  const nodeUniqueKey = matchedNode?.data?.helpers?.uniqueKey || {};
  
  const uniqueKeysForThisFrame = nodeUniqueKey[currentIndex] || null;
  const hasUniqueKey = uniqueKeysForThisFrame !== null && uniqueKeysForThisFrame.length > 0;
  
  const uniqueKeyTooltip = uniqueKeysForThisFrame;

  const handleClick = (e) => {
    e.stopPropagation();

    // find the node whose helpers.uuid equals nodeId
    const matchedNode = nodes.find(
      (n) => n.data?.helpers?.uuid === nodeId
    );

    if (matchedNode) {
      setSelectedNode(matchedNode);
      setExpandedEdgeId(null)
    } else {
      console.warn("No node found for uuid:", nodeId);
    }
  };

  const handleDoubleClick = (e) => {
    e.stopPropagation();

    setExpandedNodeId(nodeId);
    setExpandedEdgeId(null)

    if (e.shiftKey) {
      // SHIFT + double-click → open Graph View
      setGraphView(true);
      setListView(false);
    } else {
      // Double-click → open List View (default)
      setListView(true);
      setGraphView(false);
    }
  };

  return (
    <Box
      onClick={handleClick}
      onDoubleClick={handleDoubleClick}
      sx={{
        ...chipSx(color, isSelected || isExpanded),
        position: "absolute",
        left: anchorX,
        top: anchorY + offsetY,
        transform: "translateX(-50%)",
        minWidth,
        justifyContent: "center",
        zIndex,
      }}
      onContextMenu={(e) => {
        e.preventDefault();
        e.stopPropagation();

        setContextMenu({
          x: e.clientX,
          y: e.clientY,
          camera,
          nodeId,
          mode: "cameraAssign",  // 🔥 NEW, 
          bbox: "none"
        });
      }}
    >
      <Box component="span" sx={chipTextSx}>{label}</Box>
      <span
        title={uniqueKeyTooltip}
        onClick={(e) => {
          e.stopPropagation();
          e.preventDefault();
          setContextMenu({
            x: e.clientX,
            y: e.clientY,
            mode: "uniqueKeySelect",
            nodeId
          });
        }}
        style={starStyle}
      >
        {hasUniqueKey ? "★" : "☆"}
      </span>
    </Box>
  );
};

// Labels re-render only when their own props (position, colour, text, ...) change.
export const SvgPointLabel = React.memo(SvgPointLabelImpl);
export const NodeLabel = React.memo(NodeLabelImpl);
