// src/components/TemplateContext.js
// Node and edge templates are loaded from static JSON files shipped with the app.
// Changes made while annotating (new types, properties, edge labels, colours) are kept
// in memory for the current session only.
import React, { createContext, useContext, useEffect, useRef, useState } from "react";

const TemplateContext = createContext();
export const useTemplates = () => useContext(TemplateContext);

const NODE_TEMPLATES_URL = `${process.env.PUBLIC_URL}/templates/node_templates.json`;
const EDGE_TEMPLATES_URL = `${process.env.PUBLIC_URL}/templates/edge_templates.json`;

// default_properties may be stored as a list or as a JSON-encoded string.
function parseDefaults(raw) {
    if (Array.isArray(raw)) return raw;
    if (typeof raw === "string") {
        try {
            const parsed = JSON.parse(raw);
            return Array.isArray(parsed) ? parsed : [];
        } catch {
            return [];
        }
    }
    return [];
}

export function TemplateProvider({ children }) {
    const [isTemplatesReady, setTemplatesReady] = useState(false);
    const [loadError, setLoadError] = useState(null);
    const templatesRef = useRef({});
    const edgeTemplatesRef = useRef({});
    const [propertyOptions, setPropertyOptions] = useState({});
    const [edgeLabelOptions, setEdgeLabelOptions] = useState({});

    useEffect(() => {
        const load = async () => {
            try {
                const [nodeRows, edgeRows] = await Promise.all([
                    fetch(NODE_TEMPLATES_URL).then((r) => r.json()),
                    fetch(EDGE_TEMPLATES_URL).then((r) => r.json()),
                ]);

                const templates = {};
                const options = {};
                nodeRows.forEach((tpl) => {
                    const defaults = parseDefaults(tpl.default_properties);
                    templates[tpl.type] = {
                        type: tpl.type,
                        label: tpl.label,
                        color: tpl.color,
                        defaultProperties: defaults,
                    };
                    defaults.forEach((p) => {
                        if (!options[tpl.type]) options[tpl.type] = {};
                        options[tpl.type][p.key] = Array.isArray(p.values) ? p.values.filter(Boolean) : [];
                    });
                });

                const grouped = {};
                edgeRows.forEach((row) => {
                    if (!grouped[row.category]) grouped[row.category] = [];
                    if (!grouped[row.category].includes(row.label)) grouped[row.category].push(row.label);
                });

                templatesRef.current = templates;
                edgeTemplatesRef.current = grouped;
                setPropertyOptions(options);
                setEdgeLabelOptions(grouped);
                setTemplatesReady(true);
            } catch (err) {
                console.error("Error loading templates", err);
                setLoadError(String(err));
            }
        };
        load();
    }, []);

    const createNodeType = async (typeName, label, color) => {
        const type = typeName.toLowerCase();
        templatesRef.current[type] = {
            type,
            label: label || typeName,
            color: color || "#81ecec",
            defaultProperties: [],
        };
    };

    const addEdgeTemplateLabel = async (category, label) => {
        const current = edgeTemplatesRef.current[category] || [];
        if (current.includes(label)) return;
        edgeTemplatesRef.current[category] = [...current, label];
        setEdgeLabelOptions({ ...edgeTemplatesRef.current });
    };

    const addTemplateProperty = async (type, key, values, locked = false) => {
        const template = templatesRef.current[type];
        if (!template) return;

        const existing = template.defaultProperties.find((p) => p.key === key);
        if (existing) {
            existing.values = Array.from(new Set([...(existing.values || []), ...values]));
            if (typeof existing.locked !== "boolean") {
                existing.locked = !!locked;
            }
        } else {
            template.defaultProperties.push({ key, values, locked });
        }
    };

    const updateTypeColor = async (type, color) => {
        if (templatesRef.current[type]) {
            templatesRef.current[type].color = color;
        }
    };

    return (
        <TemplateContext.Provider
            value={{
                templatesRef,
                edgeTemplatesRef,
                propertyOptions,
                edgeLabelOptions,
                isTemplatesReady,
                createNodeType,
                addTemplateProperty,
                updateTypeColor,
                addEdgeTemplateLabel,
            }}
        >
            {isTemplatesReady
                ? children
                : <div style={{ color: "white", padding: 20 }}>{loadError ? `Could not load templates: ${loadError}` : "Loading templates..."}</div>}
        </TemplateContext.Provider>
    );
}
