// Sidebar with the released logs: search, scroll and pick the log to annotate.
import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  Box, Drawer, IconButton, InputAdornment, List, ListItemButton, TextField, Tooltip, Typography,
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import CloseIcon from "@mui/icons-material/Close";
import { hasAnyDraft } from "../utils/drafts";
import { ui } from "../theme";

export default function LogDrawer({ open, onClose, currentLog, onSelect, draftVersion }) {
  const [logs, setLogs] = useState([]);
  const [error, setError] = useState(null);
  const [query, setQuery] = useState("");
  const selectedRef = useRef(null);

  useEffect(() => {
    fetch(`${process.env.PUBLIC_URL}/logs.json`)
      .then((r) => r.json())
      .then(setLogs)
      .catch((err) => setError(String(err)));
  }, []);

  const filtered = useMemo(
    () => logs.filter((l) => l.logid.toLowerCase().includes(query.trim().toLowerCase())),
    [logs, query]
  );

  // Which logs have local edits (recomputed when the drawer opens or a draft changes).
  const edited = useMemo(
    () => new Set(open ? logs.filter((l) => hasAnyDraft(l.logid)).map((l) => l.logid) : []),
    // draftVersion is not read here but signals that localStorage changed.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [logs, open, draftVersion]
  );

  // Scroll the current log into view when the drawer opens.
  useEffect(() => {
    if (open && selectedRef.current) {
      selectedRef.current.scrollIntoView({ block: "center" });
    }
  }, [open, logs]);

  return (
    <Drawer
      anchor="left"
      open={open}
      onClose={onClose}
      PaperProps={{
        sx: {
          width: 360,
          maxWidth: "90vw",
          bgcolor: ui.surface,
          borderRight: `1px solid ${ui.border}`,
          borderRadius: 0,
          display: "flex",
          flexDirection: "column",
        },
      }}
    >
      <Box sx={{ p: 2, pb: 1.5 }}>
        <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", mb: 0.5 }}>
          <Typography sx={{ color: "primary.main", fontWeight: 600, fontSize: 12, letterSpacing: "0.08em", textTransform: "uppercase" }}>
            MapVQA logs
          </Typography>
          <IconButton size="small" onClick={onClose} aria-label="Close log list">
            <CloseIcon fontSize="small" />
          </IconButton>
        </Box>
        <Typography sx={{ color: "text.secondary", fontSize: 12, mb: 1.5 }}>
          {logs.length} released Argoverse 2 training logs. Edits are autosaved in this browser per log and mode.
        </Typography>
        <TextField
          size="small"
          fullWidth
          placeholder="Search log id"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon fontSize="small" />
              </InputAdornment>
            ),
          }}
        />
      </Box>

      {error && (
        <Typography color="error" sx={{ px: 2, fontSize: 12 }}>
          Could not load the log list: {error}
        </Typography>
      )}

      <List dense sx={{ flex: 1, overflowY: "auto", px: 1, py: 0 }}>
        {filtered.map((log) => {
          const isCurrent = log.logid === currentLog;
          return (
            <ListItemButton
              key={log.logid}
              ref={isCurrent ? selectedRef : undefined}
              selected={isCurrent}
              onClick={() => onSelect(log.logid)}
              sx={{
                borderRadius: "10px",
                mb: 0.5,
                py: 0.75,
                alignItems: "flex-start",
                "&.Mui-selected": { bgcolor: "rgba(244,67,54,0.14)" },
                "&.Mui-selected:hover": { bgcolor: "rgba(244,67,54,0.22)" },
              }}
            >
              <Box sx={{ minWidth: 0, flex: 1 }}>
                <Typography noWrap sx={{ fontFamily: ui.mono, fontSize: 12, color: isCurrent ? "primary.main" : "text.primary" }}>
                  {log.logid}
                </Typography>
                <Typography sx={{ fontSize: 11, color: "text.secondary" }}>
                  {log.frames} frames · {log.nodes} nodes · {log.edges} edges
                </Typography>
              </Box>
              {edited.has(log.logid) && (
                <Tooltip title="Has local edits">
                  <Box sx={{ width: 8, height: 8, borderRadius: "50%", bgcolor: "secondary.main", mt: 0.75, ml: 1, flexShrink: 0 }} />
                </Tooltip>
              )}
            </ListItemButton>
          );
        })}
      </List>

    </Drawer>
  );
}
