export function connectIntersections(newNode, nodes, visibleAt, intersectVisible, setPendingEdges) {
  const edges = [];
  const type = newNode.data.type;

  const findNode = (uuid, nodeType) =>
    nodes.find(
      (n) =>
        n.data?.type === nodeType &&
        String(n.data?.helpers?.uuid) === String(uuid)
    );

  // ---------- Case A: Intersection ----------
  if (type === "intersection") {
    const {
      incoming_lanes = [],
      outgoing_lanes = [],
      pedestrian_crossings = [],
      turn_relations = [],
    } = newNode.data.helpers || {};

    pedestrian_crossings.forEach((uuid) => {
      const crossing = findNode(uuid, "crossing");
      if (!crossing) return;
      const commonVisible = intersectVisible(Object.keys(crossing.data?.visibleAt).map(Number), visibleAt);
      if (!commonVisible.length) return;
      // edges.push(makeEdge(crossing.id, newNode.id, "is on", "static", commonVisible));
      edges.push({
        source: crossing.id,
        target: newNode.id,
        type: "static",       // or dynamic
        category: "location", // location | occlusion | impact | regulation
        label: "is on",
        description: null,
        rule: null,
        targets: null
      });
    });

    incoming_lanes.forEach((uuid) => {
      const lane = findNode(uuid, "lane");
      if (!lane) return;
      const commonVisible = intersectVisible(Object.keys(lane.data?.visibleAt).map(Number), visibleAt);
      if (!commonVisible.length) return;
      // edges.push(makeEdge(lane.id, newNode.id, "leads up to", "static", commonVisible));
      setPendingEdges(prev => [
        ...prev,
        {
          id: crypto.randomUUID(),
          from: lane.data.helpers.uuid,
          to: newNode.data.helpers.uuid,
          source: lane.id,
          target: newNode.id,
          type: "approaches",
          visibleAt: commonVisible
        }
      ]);
    });

    outgoing_lanes.forEach((uuid) => {
      const lane = findNode(uuid, "lane");
      if (!lane) return;
      const commonVisible = intersectVisible(Object.keys(lane.data?.visibleAt).map(Number), visibleAt);
      if (!commonVisible.length) return;
      setPendingEdges(prev => [
        ...prev,
        {
          id: crypto.randomUUID(),
          from: lane.data.helpers.uuid,
          to: newNode.data.helpers.uuid,
          source: lane.id,
          target: newNode.id,
          type: "leaves",
          visibleAt: commonVisible
        }
      ]);
    });

    turn_relations.forEach(({ incoming, outgoing, turn }) => {
      const laneIn = findNode(incoming, "lane");
      const laneOut = findNode(outgoing, "lane");
      if (!laneIn || !laneOut) return;
      const commonVisible = intersectVisible(
        Object.keys(laneIn.data?.visibleAt).map(Number),
        Object.keys(laneOut.data?.visibleAt).map(Number),
        visibleAt
      );
      if (!commonVisible.length) return;
      // edges.push(
      //   makeEdge(
      //     laneIn.id,
      //     laneOut.id,
      //     turn === "straight"
      //       ? `continues ahead into`
      //       : `turns ${turn} into`,
      //     "static",
      //     commonVisible
      //   )
      // );
      edges.push({
        source: laneIn.id,
        target: laneOut.id,
        type: "static",       // or dynamic
        category: "location", // location | occlusion | impact | regulation
        label: turn === "straight"
          ? `continues ahead into`
          : `turns ${turn} into`,
        description: null,
        rule: null,
        targets: null
      });
    });
  }

  // ---------- Case A2: Split ----------
  if (type === "split") {
    let { incoming = [], outgoing = [] } = newNode.data.helpers || {};

    // 🔧 normalise to array
    if (!Array.isArray(incoming)) incoming = [incoming];
    if (!Array.isArray(outgoing)) outgoing = [outgoing];

    incoming.forEach((uuid) => {
      const lane = findNode(uuid, "lane");
      if (!lane) return;
      const commonVisible = intersectVisible(Object.keys(lane.data?.visibleAt).map(Number), visibleAt);
      if (commonVisible.length)
        // edges.push(makeEdge(lane.id, newNode.id, "leads to", "static", commonVisible));
        edges.push({
          source: lane.id,
          target: newNode.id,
          type: "static",       // or dynamic
          category: "location", // location | occlusion | impact | regulation
          label: "leads to",
          description: null,
          rule: null,
          targets: null
        });
    });

    outgoing.forEach((uuid) => {
      const lane = findNode(uuid, "lane");
      if (!lane) return;
      const commonVisible = intersectVisible(Object.keys(lane.data?.visibleAt).map(Number), visibleAt);
      if (commonVisible.length)
        // edges.push(makeEdge(newNode.id, lane.id, "splits into", "static", commonVisible));
        edges.push({
          source: newNode.id,
          target: lane.id,
          type: "static",       // or dynamic
          category: "location", // location | occlusion | impact | regulation
          label: "splits into",
          description: null,
          rule: null,
          targets: null
        });
    });
  }

  // ---------- Case A3: Merge ----------
  if (type === "merge") {
    let { incoming = [], outgoing = [] } = newNode.data.helpers || {};

    // Normalize to arrays
    if (!Array.isArray(incoming)) incoming = [incoming];
    if (!Array.isArray(outgoing)) outgoing = [outgoing];


    incoming.forEach((uuid) => {
      const lane = findNode(uuid, "lane");
      if (!lane) return;
      const commonVisible = intersectVisible(Object.keys(lane.data?.visibleAt).map(Number), visibleAt);
      if (commonVisible.length)
        // edges.push(makeEdge(lane.id, newNode.id, "leads to", "static", commonVisible));
        edges.push({
          source: lane.id,
          target: newNode.id,
          type: "static",       // or dynamic
          category: "location", // location | occlusion | impact | regulation
          label: "leads to",
          description: null,
          rule: null,
          targets: null
        });
    });

    outgoing.forEach((uuid) => {
      const lane = findNode(uuid, "lane");
      if (!lane) return;
      const commonVisible = intersectVisible(Object.keys(lane.data?.visibleAt).map(Number), visibleAt);
      if (commonVisible.length)
        // edges.push(makeEdge(newNode.id, lane.id, "merges into", "static", commonVisible));
        edges.push({
          source: newNode.id,
          target: lane.id,
          type: "static",       // or dynamic
          category: "location", // location | occlusion | impact | regulation
          label: "merges into",
          description: null,
          rule: null,
          targets: null
        });
    });
  }

  // ---------- Case B: Lane or Crossing added after ----------
  if (["lane", "crossing"].includes(type)) {
    const uuid = String(newNode.data?.helpers?.uuid);

    nodes.forEach((node) => {
      const nType = node.data?.type;
      if (!["intersection", "split", "merge"].includes(nType)) return;

      const helpers = node.data.helpers || {};
      const { incoming_lanes, outgoing_lanes, pedestrian_crossings, turn_relations } = helpers;
      let { incoming = [], outgoing = [] } = helpers || {};

      // Normalize to arrays
      if (!Array.isArray(incoming)) incoming = [incoming];
      if (!Array.isArray(outgoing)) outgoing = [outgoing];

      const commonVisible = intersectVisible(Object.keys(node.data?.visibleAt).map(Number), visibleAt);
      if (!commonVisible.length) return;

      // --- Intersection retroactive connections ---
      if (nType === "intersection") {
        if (incoming_lanes?.map(String).includes(uuid))
          // edges.push(makeEdge(newNode.id, node.id, "leads up to", "static", commonVisible));
          setPendingEdges(prev => [
            ...prev,
            {
              id: crypto.randomUUID(),
              from: newNode.data.helpers.uuid,
              to: node.data.helpers.uuid,
              source: newNode.id,
              target: node.id,
              type: "approaches",
              visibleAt: commonVisible
            }
          ]);
        if (outgoing_lanes?.map(String).includes(uuid))
          setPendingEdges(prev => [
            ...prev,
            {
              id: crypto.randomUUID(),
              from: newNode.data.helpers.uuid,
              to: node.data.helpers.uuid,
              source: newNode.id,
              target: node.id,
              type: "leaves",
              visibleAt: commonVisible
            }
          ]);
        if (pedestrian_crossings?.map(String).includes(uuid))
          // edges.push(makeEdge(newNode.id, node.id, "is on", "static", commonVisible));
          edges.push({
            source: newNode.id,
            target: node.id,
            type: "static",       // or dynamic
            category: "location", // location | occlusion | impact | regulation
            label: "is on",
            description: null,
            rule: null,
            targets: null
          });

        turn_relations?.forEach(({ incoming: inc, outgoing: out, turn }) => {
          if (String(inc) === uuid) {
            const laneOut = findNode(out, "lane");
            if (!laneOut) return;
            const common = intersectVisible(
              visibleAt,
              Object.keys(laneOut.data?.visibleAt).map(Number),
              Object.keys(node.data?.visibleAt).map(Number)
            );
            if (common.length)
              // edges.push(
              //   makeEdge(
              //     newNode.id,
              //     laneOut.id,
              //     turn === "straight"
              //       ? `continues ahead into`
              //       : `turns ${turn} into`,
              //     "static",
              //     common
              //   )
              // );
              edges.push({
                source: newNode.id,
                target: laneOut.id,
                type: "static",       // or dynamic
                category: "location", // location | occlusion | impact | regulation
                label: turn === "straight"
                  ? `continues ahead into`
                  : `turns ${turn} into`,
                description: null,
                rule: null,
                targets: null
              });
          }
          if (String(out) === uuid) {
            const laneIn = findNode(inc, "lane");
            if (!laneIn) return;
            const common = intersectVisible(
              visibleAt,
              Object.keys(laneIn.data?.visibleAt).map(Number),
              Object.keys(node.data?.visibleAt).map(Number)
            );
            if (common.length)
              // edges.push(
              //   makeEdge(
              //     laneIn.id,
              //     newNode.id,
              //     turn === "straight"
              //       ? `continues ${turn} into`
              //       : `turns ${turn} into`,
              //     "static",
              //     common
              //   )
              // );
              edges.push({
                source: laneIn.id,
                target: newNode.id,
                type: "static",       // or dynamic
                category: "location", // location | occlusion | impact | regulation
                label: turn === "straight"
                  ? `continues ahead into`
                  : `turns ${turn} into`,
                description: null,
                rule: null,
                targets: null
              });
          }
        });
      }

      // --- Split retroactive connections ---
      if (nType === "split") {
        if (incoming?.map(String).includes(uuid))
          // edges.push(makeEdge(newNode.id, node.id, "leads to", "static", commonVisible));
          edges.push({
            source: newNode.id,
            target: node.id,
            type: "static",       // or dynamic
            category: "location", // location | occlusion | impact | regulation
            label: "leads to",
            description: null,
            rule: null,
            targets: null
          });
        if (outgoing?.map(String).includes(uuid))
          // edges.push(makeEdge(node.id, newNode.id, "splits into", "static", commonVisible));
          edges.push({
            source: node.id,
            target: newNode.id,
            type: "static",       // or dynamic
            category: "location", // location | occlusion | impact | regulation
            label: "splits into",
            description: null,
            rule: null,
            targets: null
          });
      }

      // --- Merge retroactive connections ---
      if (nType === "merge") {
        if (incoming?.map(String).includes(uuid))
          // edges.push(makeEdge(newNode.id, node.id, "leads to", "static", commonVisible));
          edges.push({
            source: newNode.id,
            target: node.id,
            type: "static",       // or dynamic
            category: "location", // location | occlusion | impact | regulation
            label: "leads to",
            description: null,
            rule: null,
            targets: null
          });
        if (outgoing?.map(String).includes(uuid))
          // edges.push(makeEdge(node.id, newNode.id, "merges into", "static", commonVisible));
          edges.push({
            source: node.id,
            target: newNode.id,
            type: "static",       // or dynamic
            category: "location", // location | occlusion | impact | regulation
            label: "merges into",
            description: null,
            rule: null,
            targets: null
          });
      }
    });
  }

  return edges;
}