import { connectContexts } from "./connectNodes/connectObjects";
import { connectLaneNeighbors } from "./connectNodes/connectLaneNeighbors";
import { connectLaneLines } from "./connectNodes/connectLaneLines";
import { connectIntersections } from "./connectNodes/connectIntersections";
import { connectControls } from "./connectNodes/connectControls";


export function createNode({
  type,
  position,
  properties = {},
  helpers = {},
  templatesRef,
  counterRef,
  currentIndex,
  visibleAt,
  nodes = [],
  setPendingEdges
}) {
  // -------------- 🧱 Template and counters --------------
  const template = templatesRef.current[type];
  if (!template) {
    console.warn("Unknown node type:", type);
    return null;
  }



  counterRef.current[type] = (counterRef.current[type] || 0) + 1;
  const labelBase = template.label.replace(/\s+/g, "");
  const id = `${labelBase}-${counterRef.current[type]}`;

  // merge props and add lane-specific direction
  const mergedProps = { ...properties };
  const visibleAt_ = visibleAt ?? [currentIndex];
  // ensure helpers.uuid is set
  // Build uniqueKey per timestamp
  const uniqueKey = {};
  (visibleAt_ || []).forEach((ts) => {
    uniqueKey[ts] = [];
  });

  // Merge helpers, ensuring uniqueKey exists
  const mergedHelpers = {
    ...(helpers || {}),
    uuid: helpers?.uuid ?? id,
    is_complete: Object.fromEntries(
      (visibleAt_ || []).map(ts => [ts, false])
    ),
    uniqueKey: {
      ...(helpers?.uniqueKey || {}),
      ...uniqueKey
    }
  };

  // -------------- 📍 Positioning --------------
  function findFreePosition(baseX, baseY, width = 120, height = 50, padding = 40) {
    const collides = (x, y) =>
      nodes.some((n) => {
        const dx = Math.abs(x - n.position.x);
        const dy = Math.abs(y - n.position.y);
        const w2 = (width + (n.width || 120) + padding) / 2;
        const h2 = (height + (n.height || 50) + padding) / 2;
        return dx < w2 && dy < h2;
      });

    let x = baseX;
    let y = baseY;
    let step = 0;
    while (collides(x, y) && step < 200) {
      const angle = step * 0.6;
      const r = 20 + step * 5;
      x = baseX + r * Math.cos(angle);
      y = baseY + r * Math.sin(angle);
      step++;
    }
    return { x, y };
  }



  const baseX = 400 + (counterRef.current[type] % 5) * 100;
  const baseY = 300 + Math.floor(counterRef.current[type] / 5) * 80;

  // const finalPosition = position || findFreePosition(baseX, baseY);
  const finalPosition = findFreePosition(baseX, baseY);

  // -------------- 🧩 Create Node --------------
  const isVisibleDict = {};
  (visibleAt_ || []).forEach((i) => {
    isVisibleDict[i] = true;
  });

  const newNode = {
    id,
    type: "chip",
    position: finalPosition,
    data: {
      label: id,
      type,
      properties: mergedProps,
      helpers: {
        ...mergedHelpers,
      },
      visibleAt: isVisibleDict,
    },
  };

  // -------------- 🔗 Edge helpers --------------
  const intersectVisible = (a = {}, b = {}) => {
    const aKeys = Array.isArray(a) ? a : Object.keys(a).map(Number);
    const bKeys = Array.isArray(b) ? b : Object.keys(b).map(Number);
    return aKeys.filter((t) => bKeys.includes(t));
  };

  // -------------- ⚡ Edge generation (modular) --------------
  const edgeGenerators = [
    connectContexts,        // dynamic (frame-based)
    connectLaneNeighbors,   // static
    connectLaneLines,       // static
    connectIntersections,   // static
    connectControls,        // static
  ];

  // Each connect* function can return edges tagged as "static" or "dynamic"
  const allEdges = edgeGenerators.flatMap((fn) =>
    fn(newNode, nodes, visibleAt_, intersectVisible, setPendingEdges)
  );

  // -------------- ✅ Return new node + edges --------------
  return { node: newNode, edges: allEdges };
}

export function rebuildAllEdges({ nodes, setPendingEdges }) {
  const intersectVisible = (a = {}, b = {}) => {
    const aKeys = Array.isArray(a) ? a : Object.keys(a).map(Number);
    const bKeys = Array.isArray(b) ? b : Object.keys(b).map(Number);
    return aKeys.filter((t) => bKeys.includes(t));
  };

  const edgeGenerators = [
    connectLaneNeighbors,
  ];

  const allEdges = [];
  const processedNodes = [];

  for (const newNode of nodes) {
    const visibleAt_ = Object.keys(newNode.data?.visibleAt || {}).map(Number);

    // only compare current node against already-processed nodes
    const generated = edgeGenerators.flatMap((fn) =>
      fn(newNode, processedNodes, visibleAt_, intersectVisible, setPendingEdges)
    );

    allEdges.push(...generated);

    // now add current node to processed set
    processedNodes.push(newNode);
  }

  return { deduped: allEdges };
}