/**
 * 🟥 connectControls — static regulatory relationships
 * ------------------------------------------------------------
 * Connects:
 *   - traffic_light → lane
 *   - sign → lane
 * using lane.helpers.topoTL
 * ------------------------------------------------------------
 * All edges are STATIC (non-temporal)
 */
export function connectControls(newNode, nodes, visibleAt, intersectVisible) {
  const edges = [];
  const type = newNode.data.type;


  const isControl = ["traffic_light", "sign", "road_marking"].includes(type);
  const isLane = type === "lane";

  // ---------- 1️⃣ Case A: Control node added first ----------
  if (isControl) {
    const controlUuid = String(newNode.data?.helpers?.uuid);

    nodes
      .filter((n) => n.data?.type === "lane")
      .forEach((laneNode) => {
        const topoTL = laneNode.data?.helpers?.topoTL || [];
        if (!topoTL.map(String).includes(controlUuid)) return;

        const commonVisible = intersectVisible(Object.keys(laneNode.data?.visibleAt).map(Number), visibleAt);
        if (!commonVisible.length) return;

        // edges.push(
        //   makeEdge(newNode.id, laneNode.id, "controls", "static", commonVisible)
        // );
        edges.push({
          source: newNode.id,
          target: laneNode.id,
          type: "static",       // or dynamic
          category: "regulation", // location | occlusion | impact | regulation
          label: "controls",
          description: null,
          rule: null,
          targets: "ALL"
        });
      });
  }

  // ---------- 2️⃣ Case B: Lane node added later ----------
  if (isLane) {
    const topoTL = newNode.data?.helpers?.topoTL || [];

    nodes
      .filter((n) => ["traffic_light", "sign", "road_marking"].includes(n.data?.type))
      .forEach((controlNode) => {
        const ctrlUuid = String(controlNode.data?.helpers?.uuid);
        if (!topoTL.map(String).includes(ctrlUuid)) return;

        const commonVisible = intersectVisible(Object.keys(controlNode.data?.visibleAt).map(Number), visibleAt);
        if (!commonVisible.length) return;

        // edges.push(
        //   makeEdge(controlNode.id, newNode.id, "controls", "static", commonVisible)
        // );
        edges.push({
          source: controlNode.id,
          target: newNode.id,
          type: "static",       // or dynamic
          category: "regulation", // location | occlusion | impact | regulation
          label: "controls",
          description: null,
          rule: null,
          targets: "ALL"
        });
      });
  }

  return edges;
}