// When a lane is created, connect any existing lane_lines that reference it
export function connectLaneLines(newNode, nodes, visibleAt, intersectVisible) {
  const edges = [];

  // === Case 1: new lane_line ===
  if (newNode.data.type === "lane_line") {
    const { uuid, connected = [], left_of = [], right_of = [] } = newNode.data.helpers || {};

    const findLaneByUuid = (uuid) =>
      nodes.find((n) => n?.data?.type === "lane" && String(n.data?.helpers?.uuid) === String(uuid));
    const findLineByUuid = (uuid) =>
      nodes.find((n) => n?.data?.type === "lane_line" && String(n.data?.helpers?.uuid) === String(uuid));


    connected.forEach((sucUuid) => {
      const target = findLineByUuid(sucUuid);
      if (!target) return;
      const commonVisible = intersectVisible(Object.keys(target.data?.visibleAt).map(Number), visibleAt);
      if (commonVisible.length)
        //     edges.push(
        //   makeEdge(newNode.id, target.id, "is changing into", "static", commonVisible));
        edges.push({
          source: newNode.id,
          target: target.id,
          type: "static",       // or dynamic
          category: "location", // location | occlusion | impact | regulation
          label: "is changing into",
          description: null,
          rule: null,
          targets: null
        });

    });
    left_of.forEach((laneUuid) => {
      const leftLane = findLaneByUuid(laneUuid);
      if (!leftLane) return;
      const commonVisible = intersectVisible(Object.keys(leftLane.data?.visibleAt).map(Number), visibleAt);
      if (commonVisible.length)
        // edges.push(makeEdge(newNode.id, leftLane.id, "is left marking of", "static", commonVisible));
        edges.push({
          source: newNode.id,
          target: leftLane.id,
          type: "static",       // or dynamic
          category: "location", // location | occlusion | impact | regulation
          label: "is left marking of",
          description: null,
          rule: null,
          targets: null
        });
    });

    right_of.forEach((laneUuid) => {
      const rightLane = findLaneByUuid(laneUuid);
      if (!rightLane) return;
      const commonVisible = intersectVisible(Object.keys(rightLane.data?.visibleAt).map(Number), visibleAt);
      if (commonVisible.length)
        // edges.push(makeEdge(newNode.id, rightLane.id, "is right marking of", "static", commonVisible));
        edges.push({
          source: newNode.id,
          target: rightLane.id,
          type: "static",       // or dynamic
          category: "location", // location | occlusion | impact | regulation
          label: "is right marking of",
          description: null,
          rule: null,
          targets: null
        });
    });

    // retroactive lane_line → newNode successor
    nodes
      .filter((n) => n.data?.type === "lane_line")
      .forEach((existing) => {
        const ex = existing.data?.helpers || {};
        if ((ex.successors || []).includes(String(uuid))) {
          const commonVisible = intersectVisible(Object.keys(existing.data?.visibleAt).map(Number), visibleAt);
          if (commonVisible.length)
            // edges.push(makeEdge(existing.id, newNode.id, "is changing into", "static", commonVisible));
            edges.push({
              source: existing.id,
              target: newNode.id,
              type: "static",       // or dynamic
              category: "location", // location | occlusion | impact | regulation
              label: "is changing into",
              description: null,
              rule: null,
              targets: null
            });
        }
      });

    return edges;
  }

  // === Case 2: new lane ===
  if (newNode.data.type === "lane") {
    const laneUuid = String(newNode.data?.helpers?.uuid);

    nodes
      .filter((n) => n.data?.type === "lane_line")
      .forEach((line) => {
        const { left_of = [], right_of = [] } = line.data.helpers || {};
        const commonVisible = intersectVisible(Object.keys(line.data?.visibleAt).map(Number), visibleAt);
        if (!commonVisible.length) return;

        if (left_of.includes(laneUuid))
          // edges.push(makeEdge(line.id, newNode.id, "is left marking of", "static", commonVisible));
          edges.push({
            source: line.id,
            target: newNode.id,
            type: "static",       // or dynamic
            category: "location", // location | occlusion | impact | regulation
            label: "is left marking of",
            description: null,
            rule: null,
            targets: null
          });

        if (right_of.includes(laneUuid))
          // edges.push(makeEdge(line.id, newNode.id, "is right marking of", "static", commonVisible));
          edges.push({
            source: line.id,
            target: newNode.id,
            type: "static",       // or dynamic
            category: "location", // location | occlusion | impact | regulation
            label: "is right marking of",
            description: null,
            rule: null,
            targets: null
          });
      });

    return edges;
  }

  return [];
}