// transformUtils.js
export function make_T_world_from_ego(pose) {
  const [x, y, z] = pose.translation;
  const R = pose.rotation;
  return [
    [R[0][0], R[0][1], R[0][2], x],
    [R[1][0], R[1][1], R[1][2], y],
    [R[2][0], R[2][1], R[2][2], z],
    [0, 0, 0, 1]
  ];
}

export function make_T_cam_from_ego(R, t) {
  return [
    [R[0][0], R[0][1], R[0][2], t[0][0]],
    [R[1][0], R[1][1], R[1][2], t[1][0]],
    [R[2][0], R[2][1], R[2][2], t[2][0]],
    [0, 0, 0, 1]
  ];
}

export function invert_T(T) {
  const R = T.slice(0, 3).map(row => row.slice(0, 3));
  const t = [T[0][3], T[1][3], T[2][3]];
  const Rt = R[0].map((_, j) => R.map(row => row[j]));
  const t_inv = [
    -(Rt[0][0] * t[0] + Rt[0][1] * t[1] + Rt[0][2] * t[2]),
    -(Rt[1][0] * t[0] + Rt[1][1] * t[1] + Rt[1][2] * t[2]),
    -(Rt[2][0] * t[0] + Rt[2][1] * t[1] + Rt[2][2] * t[2])
  ];
  return [
    [Rt[0][0], Rt[0][1], Rt[0][2], t_inv[0]],
    [Rt[1][0], Rt[1][1], Rt[1][2], t_inv[1]],
    [Rt[2][0], Rt[2][1], Rt[2][2], t_inv[2]],
    [0, 0, 0, 1]
  ];
}

export function multiply4x4(A, B) {
  const C = [];
  for (let i = 0; i < 4; ++i) {
    C[i] = [];
    for (let j = 0; j < 4; ++j) {
      C[i][j] = A[i].reduce((sum, _, k) => sum + A[i][k] * B[k][j], 0);
    }
  }
  return C;
}