import React, { useState } from "react";
import {
    Dialog, DialogTitle, DialogActions, DialogContent,
    Box,
    Button,
    Divider,
    TextField,
    ClickAwayListener,
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import { useGraph } from "../components/GraphContext";
import { useTemplates } from "../components/TemplateContext";
/**
 * NodeTypePalette
 * ----------------------------
 * Reusable palette component for selecting and creating node types.
 *
 * Props:
 *  - open: boolean → controls visibility
 *  - position: { x, y } → absolute coordinates for placement
 *  - onClose(): void → called when clicking outside
 *  - templatesRef: React ref to node templates
 *  - onSelectType(key: string): void → triggered when user selects a node type
 *  - onCreateNew(): void → triggered when "+ New" is clicked
 */
export default function NodeTypePalette({
    open,
    top, left,
    setPaletteOpen,
    onSelectType = null
}) {
    const [searchTerm, setSearchTerm] = useState("");
    const { addNode } = useGraph();
    const { templatesRef, createNodeType } = useTemplates();
    const [createNodeDialogOpen, setCreateNodeDialogOpen] = useState(false);
    const [newNodeType, setNewNodeType] = useState({
        key: "",
        label: "",
        color: "#cccccc",
    });
    if (!open) return null;

    const templates = templatesRef?.current || {};

    const filtered = Object.entries(templates)
        .filter(([key, tpl]) => {
            if (!searchTerm) return true;
            const term = searchTerm.toLowerCase();
            return (
                tpl.label.toLowerCase().includes(term) ||
                key.toLowerCase().includes(term)
            );
        })
        .sort(([, a], [, b]) =>
            a.label.toLowerCase().localeCompare(b.label.toLowerCase())
        );

    return (

        <ClickAwayListener onClickAway={() => setPaletteOpen(false)}>
            <Box>
                <Dialog
                    open={createNodeDialogOpen}
                    onClose={() => setCreateNodeDialogOpen(false)}
                    maxWidth="xs"
                    fullWidth
                >
                    <DialogTitle>Create New Node Type</DialogTitle>
                    <DialogContent sx={{ display: "flex", flexDirection: "column", gap: 2, mt: 1 }}>
                        <TextField
                            label="Node Type Key"
                            fullWidth
                            value={newNodeType.key}
                            onChange={(e) =>
                                setNewNodeType((prev) => ({ ...prev, key: e.target.value }))
                            }
                        />
                        <TextField
                            label="Label"
                            fullWidth
                            value={newNodeType.label}
                            onChange={(e) =>
                                setNewNodeType((prev) => ({ ...prev, label: e.target.value }))
                            }
                        />
                        <TextField
                            label="Color"
                            type="color"
                            fullWidth
                            value={newNodeType.color}
                            onChange={(e) =>
                                setNewNodeType((prev) => ({ ...prev, color: e.target.value }))
                            }
                        />
                    </DialogContent>
                    <DialogActions>
                        <Button onClick={() => setCreateNodeDialogOpen(false)}>Cancel</Button>
                        <Button
                            variant="contained"
                            onClick={() => {
                                const { key, label, color } = newNodeType;
                                if (!key || !label || !color) return alert("Please fill all fields");
                                createNodeType(key, label, color)
                                setCreateNodeDialogOpen(false);
                                setNewNodeType({ key: "", label: "", color: "#cccccc" });
                            }}
                        >
                            Create
                        </Button>
                    </DialogActions>
                </Dialog>
                <Box
                    sx={{
                        position: "absolute",
                        top: top,
                        left: left,
                        transform: "translate(-50%, 0%)",
                        background: "rgba(40,40,40,0.95)",
                        border: "1px solid #444",
                        borderRadius: 2,
                        p: 1,
                        display: "flex",
                        flexDirection: "column",
                        gap: 0.8,
                        zIndex: 9999,
                        boxShadow: "0 4px 12px rgba(0,0,0,0.4)",
                        width: 400,
                        height: 300,
                    }}
                >
                    {/* Search bar + new node button */}
                    <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                        <TextField
                            placeholder="Search node type..."
                            size="medium"
                            variant="outlined"
                            onChange={(e) => setSearchTerm(e.target.value.toLowerCase())}
                            InputProps={{
                                startAdornment: (
                                    <Box sx={{ pl: 0.5, height: 30, display: "flex", alignItems: "center" }}>
                                        <SearchIcon sx={{ fontSize: 16, color: "#aaa", mr: 0.5 }} />
                                    </Box>
                                ),
                            }}
                            sx={{
                                flex: 1,
                                input: {
                                    color: "#fff",
                                    fontSize: "0.7rem",
                                    py: 0.3,
                                },
                                "& .MuiOutlinedInput-root": {
                                    backgroundColor: "rgba(60,60,60,0.8)",
                                    borderRadius: "6px",
                                    "& fieldset": { borderColor: "#555" },
                                    "&:hover fieldset": { borderColor: "#777" },
                                    "&.Mui-focused fieldset": { borderColor: "#aaa" },
                                },
                            }}
                        />

                        <Button
                            variant="outlined"
                            onClick={() => setCreateNodeDialogOpen(true)}
                            sx={{
                                textTransform: "none",
                                height: 30,
                                minWidth: 90,
                                borderRadius: 24,
                                color: "#fff",
                                borderColor: "#666",
                                fontSize: "0.7rem",
                                px: 1,
                                "&:hover": { borderColor: "#aaa", background: "#222" },
                            }}
                        >
                            + New
                        </Button>
                    </Box>

                    <Divider />

                    {/* Node chips */}
                    <Box
                        sx={{
                            display: "flex",
                            flexWrap: "wrap",
                            overflowY: "auto",
                            gap: 0.5,
                            p: 0.2,
                        }}
                    >
                        {filtered.map(([key, tpl]) => (
                            <Button
                                key={key}
                                size="small"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    if (onSelectType) { onSelectType(key); }
                                    else { addNode(key, undefined); }
                                    setPaletteOpen(false);
                                }}
                                sx={{
                                    background: tpl.color || "#ccc",
                                    color: "#000",
                                    textTransform: "none",
                                    borderRadius: "9999px",
                                    fontSize: "0.65rem",
                                    fontWeight: 500,
                                    px: 1,
                                    height: "20px",
                                    "&:hover": { opacity: 0.8, background: tpl.color || "#ccc" },
                                }}
                            >
                                {tpl.label}
                            </Button>
                        ))}
                    </Box>
                </Box>
            </Box>
        </ClickAwayListener>
    );
}