import { useEffect, useState } from "react";
import { HashRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import { ThemeProvider, CssBaseline, Typography, Box, Button } from "@mui/material";
import DesktopWindowsIcon from "@mui/icons-material/DesktopWindows";
import theme from "./theme.js";
import { GraphProvider } from "./components/GraphContext.js";
import { TemplateProvider } from "./components/TemplateContext.js";
import Clicker from "./pages/Clicker";
import "./App.css";

// Log opened when the app is started without one (falls back to the first released log).
const DEFAULT_LOG = "34fe8fbd-2b1a-3552-94c4-e80d1e85e5c2";

// Opening the app without a log goes straight to the default log with its annotation.
function FirstLog() {
  const [first, setFirst] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch(`${process.env.PUBLIC_URL}/logs.json`)
      .then((r) => r.json())
      .then((logs) => {
        const preferred = logs.find((l) => l.logid === DEFAULT_LOG);
        setFirst((preferred || logs[0])?.logid ?? null);
      })
      .catch((err) => setError(String(err)));
  }, []);

  if (error) return <Typography sx={{ p: 3 }} color="error">Could not load the log list: {error}</Typography>;
  if (!first) return null;
  return <Navigate to={`/main/${first}?start=annotated`} replace />;
}

// The editor needs a mouse and a large screen: narrow windows and touch-only devices get a notice instead.
const MOBILE_QUERY = "(max-width: 899px), (pointer: coarse) and (hover: none)";

function useIsMobile() {
  const get = () => typeof window !== "undefined" && window.matchMedia(MOBILE_QUERY).matches;
  const [mobile, setMobile] = useState(get);
  useEffect(() => {
    const mq = window.matchMedia(MOBILE_QUERY);
    const onChange = () => setMobile(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return mobile;
}

function MobileNotice() {
  return (
    <Box sx={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", p: 3, bgcolor: "background.default" }}>
      <Box sx={{ maxWidth: 380, textAlign: "center" }}>
        <DesktopWindowsIcon sx={{ fontSize: 44, color: "primary.main", mb: 2 }} />
        <Typography variant="h6" sx={{ mb: 1 }}>Not available on mobile</Typography>
        <Typography sx={{ color: "text.secondary", fontSize: 14, mb: 3 }}>
          The graph creator needs a larger screen and a mouse. Please open this page on a desktop or laptop computer.
        </Typography>
        <Button variant="contained" href="../">Back to the project page</Button>
      </Box>
    </Box>
  );
}

// Hash-based routes (#/main/<logid>) so the app works as a static GitHub Pages site.
function App() {
  const isMobile = useIsMobile();
  if (isMobile) {
    return (
      <ThemeProvider theme={theme}>
        <CssBaseline />
        <MobileNotice />
      </ThemeProvider>
    );
  }
  return (
    <TemplateProvider>
      <GraphProvider>
        <ThemeProvider theme={theme}>
          <CssBaseline />
          <Router>
            <Routes>
              <Route path="/main/:logid" element={<Clicker />} />
              <Route path="*" element={<FirstLog />} />
            </Routes>
          </Router>
        </ThemeProvider>
      </GraphProvider>
    </TemplateProvider>
  );
}

export default App;
